CREATE OR REPLACE FUNCTION public.buy_wakati_with_asset(p_user_id uuid, p_from_asset_symbol text, p_from_amount numeric, p_wakati_amount numeric, p_exchange_rate numeric, p_fee_percentage numeric DEFAULT 0.5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fee_amount             numeric;
  v_base_amount            numeric;
  v_total_debit            numeric;
  v_user_from_balance      numeric;
  v_treasury_wakati_before numeric;
  v_treasury_from_before   numeric;
  v_transaction_id         uuid;
BEGIN
  IF auth.uid() IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Non autorisé', 'error_code', 'FORBIDDEN');
  END IF;

  IF p_from_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Montant asset invalide', 'error_code', 'INVALID_AMOUNT');
  END IF;
  IF p_wakati_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Montant WAKATI invalide', 'error_code', 'INVALID_AMOUNT');
  END IF;
  IF p_from_asset_symbol = 'WAKATI' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Impossible d''acheter WAKATI avec WAKATI', 'error_code', 'INVALID_ASSET');
  END IF;

  v_base_amount := p_from_amount;
  v_fee_amount  := ROUND(v_base_amount * (p_fee_percentage / 100), 8);
  v_total_debit := v_base_amount + v_fee_amount;

  SELECT available_balance INTO v_user_from_balance
  FROM user_balances WHERE user_id = p_user_id AND asset_symbol = p_from_asset_symbol FOR UPDATE;

  IF NOT FOUND OR v_user_from_balance < v_total_debit THEN
    RETURN jsonb_build_object('success', false, 'message', 'Solde insuffisant pour ' || p_from_asset_symbol, 'error_code', 'INSUFFICIENT_BALANCE');
  END IF;

  SELECT balance INTO v_treasury_wakati_before FROM treasury_wallets WHERE asset_symbol = 'WAKATI' FOR UPDATE;
  IF NOT FOUND OR v_treasury_wakati_before < p_wakati_amount THEN
    RETURN jsonb_build_object('success', false, 'message', 'Liquidité WAKATI insuffisante', 'error_code', 'TREASURY_INSUFFICIENT_WAKATI');
  END IF;

  -- Debit utilisateur (actif source, base + frais)
  UPDATE user_balances SET available_balance = available_balance - v_total_debit, updated_at = now()
  WHERE user_id = p_user_id AND asset_symbol = p_from_asset_symbol;

  -- Credit utilisateur (WAKATI)
  INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)
  VALUES (p_user_id, 'WAKATI', p_wakati_amount, now())
  ON CONFLICT (user_id, asset_symbol) DO UPDATE
  SET available_balance = user_balances.available_balance + p_wakati_amount, updated_at = now();

  -- Tresorerie absorbe la part hors-frais de l'actif source
  SELECT balance INTO v_treasury_from_before FROM treasury_wallets WHERE asset_symbol = p_from_asset_symbol FOR UPDATE;
  IF FOUND THEN
    UPDATE treasury_wallets SET balance = balance + v_base_amount, updated_at = now() WHERE asset_symbol = p_from_asset_symbol;
  ELSE
    INSERT INTO treasury_wallets (asset_symbol, balance, total_collected, total_burned, total_withdrawn, updated_at)
    VALUES (p_from_asset_symbol, v_base_amount, v_base_amount, 0, 0, now());
    v_treasury_from_before := 0;
  END IF;

  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
  VALUES (p_from_asset_symbol, 'wakati_sale', v_base_amount, v_treasury_from_before, v_treasury_from_before + v_base_amount,
          p_user_id, 'Achat WAKATI - actif recu (hors frais)');

  -- Tresorerie debite les WAKATI emis vers le user
  UPDATE treasury_wallets SET balance = balance - p_wakati_amount, total_withdrawn = total_withdrawn + p_wakati_amount, updated_at = now()
  WHERE asset_symbol = 'WAKATI';

  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
  VALUES ('WAKATI', 'wakati_sale', p_wakati_amount, v_treasury_wakati_before, v_treasury_wakati_before - p_wakati_amount,
          p_user_id, 'Achat WAKATI - WAKATI emis');

  -- Frais reels (part separee, ajoutee a la tresorerie + platform_fees via la fonction commune)
  IF v_fee_amount > 0 THEN
    PERFORM collect_fee_to_platform(p_from_asset_symbol, v_fee_amount, 'wakati_purchase_fee', p_user_id, NULL);
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (p_user_id, 'buy_wakati', 'WAKATI', p_wakati_amount, p_wakati_amount, 'completed', now(),
    jsonb_build_object('from_asset', p_from_asset_symbol, 'from_amount_total', v_total_debit,
                        'base_amount', v_base_amount, 'fee_amount', v_fee_amount,
                        'fee_percentage', p_fee_percentage, 'exchange_rate', p_exchange_rate))
  RETURNING id INTO v_transaction_id;

  RETURN jsonb_build_object(
    'success', true, 'transaction_id', v_transaction_id, 'from_asset', p_from_asset_symbol,
    'from_amount_total', v_total_debit, 'base_amount', v_base_amount, 'fee_amount', v_fee_amount,
    'fee_percentage', p_fee_percentage, 'wakati_credited', p_wakati_amount, 'exchange_rate', p_exchange_rate
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', SQLERRM, 'error_code', 'INTERNAL_ERROR');
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_fee(p_asset_symbol text, p_amount numeric, p_fee_type text DEFAULT 'transfer'::text)
 RETURNS TABLE(fee_amount numeric, fee_percentage numeric, net_amount numeric, fee_details jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_fee_percentage NUMERIC := 0;
    v_fee_amount NUMERIC := 0;
    v_min_fee NUMERIC := 0.01;
BEGIN
    CASE p_fee_type
        WHEN 'transfer' THEN
            v_fee_percentage := 0.5;
            v_fee_amount := p_amount * (v_fee_percentage / 100);
            IF v_fee_amount < v_min_fee THEN v_fee_amount := v_min_fee; END IF;

        WHEN 'withdraw' THEN
            SELECT withdraw_fee INTO v_fee_amount
            FROM supported_assets
            WHERE symbol = p_asset_symbol;

            v_fee_amount := COALESCE(v_fee_amount, 0);

            IF p_amount > 0 THEN
                v_fee_percentage := (v_fee_amount / p_amount) * 100;
            ELSE
                v_fee_percentage := 0;
            END IF;

        WHEN 'swap' THEN
            v_fee_percentage := 0.5;
            v_fee_amount := p_amount * (v_fee_percentage / 100);
            IF v_fee_amount < v_min_fee THEN v_fee_amount := v_min_fee; END IF;

        ELSE
            v_fee_amount := 0;
            v_fee_percentage := 0;
    END CASE;

    fee_amount := v_fee_amount;
    fee_percentage := v_fee_percentage;
    net_amount := p_amount - v_fee_amount;

    fee_details := jsonb_build_object(
        'fee_type', p_fee_type,
        'asset_symbol', p_asset_symbol,
        'amount', p_amount,
        'min_fee_applied', (v_fee_amount = v_min_fee AND v_min_fee > 0 AND p_fee_type <> 'withdraw')
    );

    RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_net_amount()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.net_amount := NEW.amount - COALESCE(NEW.fee, 0);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_pool_apy(p_pool_id uuid, p_stake_amount numeric DEFAULT 0, p_reference_date timestamp with time zone DEFAULT now())
 RETURNS TABLE(apy numeric, mode text, details jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_pool RECORD;
    v_result_apy NUMERIC := 0;
    v_details JSONB := '{}'::jsonb;
    v_total_staked NUMERIC;
    v_rewards_remaining NUMERIC;
    v_days_remaining INTEGER;
    v_daily_budget NUMERIC;
    v_projected_total_staked NUMERIC;
    v_utilization_rate NUMERIC;
BEGIN
    -- Récupérer les informations du pool
    SELECT * INTO v_pool 
    FROM staking_pools 
    WHERE id = p_pool_id AND is_active = true;
    
    IF v_pool IS NULL THEN
        RETURN QUERY SELECT 0::NUMERIC, 'error'::TEXT, '{"error": "Pool not found or inactive"}'::jsonb;
        RETURN;
    END IF;
    
    -- Calculer le total staké actuel
    SELECT COALESCE(SUM(amount), 0) INTO v_total_staked
    FROM user_stakes 
    WHERE pool_id = p_pool_id AND status = 'active';
    
    -- Total projeté (actuel + nouveau stake)
    v_projected_total_staked := v_total_staked + p_stake_amount;
    
    CASE v_pool.apy_mode
        
        -- ── APY FIXE ──────────────────────────────────────────
        WHEN 'fixed' THEN
            v_result_apy := COALESCE(v_pool.base_apy, 0);
            v_details := jsonb_build_object(
                'mode', 'fixed',
                'base_apy', v_pool.base_apy,
                'effective_apy', ROUND(v_result_apy, 2)
            );
        
        -- ── APY DYNAMIQUE ─────────────────────────────────────
        WHEN 'dynamic' THEN
            -- Calculer le taux d'utilisation
            IF COALESCE(v_pool.total_capacity, 0) = 0 THEN
                v_utilization_rate := 0;
            ELSE
                v_utilization_rate := v_projected_total_staked / v_pool.total_capacity;
            END IF;
            
            -- APY = base_apy * (1 - utilisation) avec minimum 20% du base
            v_result_apy := v_pool.base_apy * GREATEST(1 - v_utilization_rate, 0.2);
            
            v_details := jsonb_build_object(
                'mode', 'dynamic',
                'base_apy', v_pool.base_apy,
                'effective_apy', ROUND(v_result_apy, 2),
                'utilization_rate', ROUND(v_utilization_rate * 100, 2),
                'total_staked', v_total_staked,
                'projected_staked', v_projected_total_staked,
                'total_capacity', v_pool.total_capacity
            );
        
        -- ── LAUNCHPOOL ────────────────────────────────────────
        WHEN 'launchpool' THEN
            -- Vérifier si le launchpool est valide
            IF v_pool.launchpool_end_date IS NULL 
               OR v_pool.launchpool_end_date <= p_reference_date
               OR COALESCE(v_pool.launchpool_rewards_left, 0) <= 0 THEN
                
                v_result_apy := 0;
                v_details := jsonb_build_object(
                    'mode', 'launchpool',
                    'status', 'ended',
                    'message', 'Launchpool terminé ou épuisé',
                    'effective_apy', 0
                );
                
                RETURN QUERY SELECT v_result_apy, 'launchpool'::TEXT, v_details;
                RETURN;
            END IF;

            -- Calculer les jours restants
            v_days_remaining := GREATEST(
                EXTRACT(DAY FROM (v_pool.launchpool_end_date - p_reference_date))::INTEGER,
                1
            );
            
            v_rewards_remaining := COALESCE(v_pool.launchpool_rewards_left, 0);
            
            -- Si personne n'a stake
            IF v_projected_total_staked = 0 THEN
                v_result_apy := COALESCE(v_pool.base_apy, 10.0); -- 10% par défaut
                v_details := jsonb_build_object(
                    'mode', 'launchpool',
                    'status', 'no_stakers',
                    'base_apy', v_pool.base_apy,
                    'effective_apy', ROUND(v_result_apy, 2),
                    'message', 'Pas encore de stakers - APY de base affiché'
                );
            ELSE
                -- Budget quotidien
                v_daily_budget := v_rewards_remaining / v_days_remaining;
                
                -- FORMULE : APY = (daily_budget / total_staked) × 365 × 100
                v_result_apy := (v_daily_budget / v_projected_total_staked) * 365 * 100;
                
                v_details := jsonb_build_object(
                    'mode', 'launchpool',
                    'status', 'active',
                    'total_staked', v_total_staked,
                    'projected_staked', v_projected_total_staked,
                    'rewards_remaining', ROUND(v_rewards_remaining, 2),
                    'days_remaining', v_days_remaining,
                    'daily_budget', ROUND(v_daily_budget, 4),
                    'effective_apy', ROUND(v_result_apy, 2),
                    'formula', '(daily_budget / total_staked) × 365 × 100'
                );
            END IF;
        
        -- ── AUTRE MODE (fallback) ─────────────────────────────
        ELSE
            v_result_apy := COALESCE(v_pool.base_apy, 0);
            v_details := jsonb_build_object(
                'mode', COALESCE(v_pool.apy_mode, 'unknown'),
                'base_apy', v_pool.base_apy,
                'effective_apy', ROUND(v_result_apy, 2),
                'warning', 'Mode non reconnu, utilisation du base_apy'
            );
    
    END CASE;
    
    -- S'assurer que l'APY n'est pas négatif
    v_result_apy := GREATEST(ROUND(v_result_apy, 6), 0);
    
    -- Retourner le résultat
    RETURN QUERY SELECT v_result_apy, v_pool.apy_mode, v_details;
    
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'calculate_pool_apy error (pool %): %', p_pool_id, SQLERRM;
    RETURN QUERY SELECT 
        COALESCE(v_pool.base_apy, 0)::NUMERIC, 
        COALESCE(v_pool.apy_mode, 'error')::TEXT, 
        jsonb_build_object('error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.check_balance(p_user_id uuid, p_asset text, p_amount numeric)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_balance numeric;
BEGIN
  SELECT available_balance INTO v_balance
  FROM user_balances 
  WHERE user_id = p_user_id AND asset_symbol = p_asset;
  
  RETURN COALESCE(v_balance, 0) >= p_amount;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_transaction_limit(p_user_id uuid, p_amount numeric, p_type text)
 RETURNS TABLE(allowed boolean, message text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_limits RECORD;
BEGIN
    -- Récupérer ou créer les limites
    INSERT INTO user_transaction_limits (user_id)
    VALUES (p_user_id)
    ON CONFLICT (user_id) DO NOTHING;
    
    SELECT * INTO v_limits
    FROM user_transaction_limits
    WHERE user_id = p_user_id
    FOR UPDATE;
    
    -- Reset si nécessaire
    IF v_limits.last_daily_reset < CURRENT_DATE THEN
        UPDATE user_transaction_limits
        SET 
            daily_withdraw_used = 0,
            daily_deposit_used = 0,
            last_daily_reset = CURRENT_DATE
        WHERE user_id = p_user_id;
        
        SELECT * INTO v_limits
        FROM user_transaction_limits
        WHERE user_id = p_user_id;
    END IF;
    
    -- Vérifier limites
    IF p_type = 'withdraw' THEN
        IF (v_limits.daily_withdraw_used + p_amount) > v_limits.daily_withdraw_limit THEN
            RETURN QUERY SELECT FALSE, 'Limite quotidienne de retrait dépassée';
            RETURN;
        END IF;
    ELSIF p_type = 'deposit' THEN
        IF (v_limits.daily_deposit_used + p_amount) > v_limits.daily_deposit_limit THEN
            RETURN QUERY SELECT FALSE, 'Limite quotidienne de dépôt dépassée';
            RETURN;
        END IF;
    END IF;
    
    RETURN QUERY SELECT TRUE, 'Limite OK';
END;
$function$

CREATE OR REPLACE FUNCTION public.check_user_address(p_user_id uuid, p_asset_symbol text)
 RETURNS TABLE(status text, id uuid, asset_symbol text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, created_at timestamp with time zone, error_message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_symbol text := upper(trim(p_asset_symbol));
  v_pending record;
  v_status int;
  v_body jsonb;
begin
  if auth.uid() is distinct from p_user_id
     and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Non autorisé';
  end if;

  return query
    select 'ready'::text, ua.id, ua.asset_symbol, ua.network, ua.address,
           ua.derivation_index, ua.is_active, ua.cached_balance, ua.created_at, null::text
    from public.user_addresses ua
    where ua.user_id = p_user_id and ua.asset_symbol = v_symbol
    limit 1;
  if found then return; end if;

  select * into v_pending from public.pending_address_requests par
  where par.user_id = p_user_id and par.asset_symbol = v_symbol;

  if not found then
    return query select 'failed'::text, null::uuid, v_symbol, null::text, null::text,
                        null::integer, null::boolean, null::numeric, null::timestamptz,
                        'Aucune génération en cours — relancez'::text;
    return;
  end if;

  select r.status_code, r.content::jsonb into v_status, v_body
  from net._http_response r where r.id = v_pending.request_id;

  if v_status is null then
    return query select 'pending'::text, null::uuid, v_symbol, null::text, null::text,
                        null::integer, null::boolean, null::numeric, null::timestamptz, null::text;
    return;
  end if;

  delete from public.pending_address_requests par
  where par.user_id = p_user_id and par.asset_symbol = v_symbol;

  if v_status <> 200 or coalesce((v_body->>'success')::boolean, false) = false then
    return query select 'failed'::text, null::uuid, v_symbol, null::text, null::text,
                        null::integer, null::boolean, null::numeric, null::timestamptz,
                        coalesce(v_body->>'error', 'Erreur inconnue (HTTP ' || v_status || ')');
    return;
  end if;

  insert into public.user_addresses (
    user_id, asset_symbol, address, derivation_index, network, is_active, cached_balance
  )
  values (
    p_user_id,
    upper(v_body->'data'->>'asset_symbol'),
    v_body->'data'->>'address',
    (v_body->'data'->>'derivation_index')::integer,
    v_body->'data'->>'network',
    true, 0
  )
  on conflict (user_id, asset_symbol) do update
    set address = excluded.address,
        derivation_index = excluded.derivation_index,
        network = excluded.network,
        is_active = true;

  return query
    select 'ready'::text, ua.id, ua.asset_symbol, ua.network, ua.address,
           ua.derivation_index, ua.is_active, ua.cached_balance, ua.created_at, null::text
    from public.user_addresses ua
    where ua.user_id = p_user_id and ua.asset_symbol = v_symbol
    limit 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_user_profile(p_user_id uuid, p_username text, p_referral_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referrer           RECORD;
  v_referral_applied    boolean := false;
  v_referrer_username   text;
  v_bonus_referred      numeric := 300;
  v_bonus_referrer      numeric := 200;
  v_bonus_asset         text    := 'WAKATI';
  v_clean_username      text;
BEGIN
  IF auth.uid() IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN', 'message', 'Action non autorisée');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'USER_NOT_FOUND', 'message', 'Utilisateur introuvable');
  END IF;

  IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id AND profile_completed = true) THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALREADY_COMPLETED', 'message', 'Profil déjà complété');
  END IF;

  v_clean_username := LOWER(TRIM(p_username));
  v_clean_username := REGEXP_REPLACE(v_clean_username, '[^a-zA-Z0-9_]', '', 'g');

  IF LENGTH(v_clean_username) > 20 THEN
    v_clean_username := SUBSTRING(v_clean_username FROM 1 FOR 20);
  END IF;

  IF LENGTH(v_clean_username) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'USERNAME_TOO_SHORT', 'message', 'Le username doit faire au moins 3 caractères');
  END IF;

  IF EXISTS (SELECT 1 FROM public.users WHERE username = v_clean_username AND id != p_user_id) THEN
    v_clean_username := SUBSTRING(v_clean_username FROM 1 FOR 18) || SUBSTRING(MD5(RANDOM()::text) FROM 1 FOR 2);
    IF EXISTS (SELECT 1 FROM public.users WHERE username = v_clean_username AND id != p_user_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'USERNAME_TAKEN', 'message', 'Ce username est déjà pris, essaie un autre');
    END IF;
  END IF;

  IF p_referral_code IS NOT NULL AND TRIM(p_referral_code) != '' THEN

    IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id AND referred_by IS NOT NULL) THEN
      RETURN jsonb_build_object('success', false, 'error', 'ALREADY_REFERRED', 'message', 'Tu as déjà utilisé un code referral');
    END IF;

    SELECT id, username INTO v_referrer
    FROM public.users
    WHERE referral_code = UPPER(TRIM(p_referral_code))
      AND id != p_user_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'INVALID_CODE', 'message', 'Code referral invalide ou inexistant');
    END IF;

    v_referral_applied  := true;
    v_referrer_username := v_referrer.username;

    UPDATE public.users SET referred_by = v_referrer.id, updated_at = NOW() WHERE id = p_user_id;

    -- Bonus filleul (300 WAKATI), finance par la tresorerie
    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)
    VALUES (p_user_id, v_bonus_asset, v_bonus_referred)
    ON CONFLICT (user_id, asset_symbol) DO UPDATE
      SET available_balance = user_balances.available_balance + v_bonus_referred, updated_at = NOW();

    INSERT INTO public.transactions (user_id, type, asset_symbol, amount, status, metadata)
    VALUES (p_user_id, 'referral_bonus', v_bonus_asset, v_bonus_referred, 'completed',
      jsonb_build_object('referrer_id', v_referrer.id, 'referrer_username', v_referrer_username, 'recipient_type', 'referred'));

    PERFORM fn_treasury_debit_for_payout(v_bonus_asset, v_bonus_referred, p_user_id, 'Bonus parrainage - filleul');

    -- Bonus parrain (200 WAKATI), finance par la tresorerie
    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)
    VALUES (v_referrer.id, v_bonus_asset, v_bonus_referrer)
    ON CONFLICT (user_id, asset_symbol) DO UPDATE
      SET available_balance = user_balances.available_balance + v_bonus_referrer, updated_at = NOW();

    INSERT INTO public.transactions (user_id, type, asset_symbol, amount, status, metadata)
    VALUES (v_referrer.id, 'referral_bonus', v_bonus_asset, v_bonus_referrer, 'completed',
      jsonb_build_object('referred_user_id', p_user_id, 'referred_username', v_clean_username, 'recipient_type', 'referrer'));

    PERFORM fn_treasury_debit_for_payout(v_bonus_asset, v_bonus_referrer, v_referrer.id, 'Bonus parrainage - parrain');

    INSERT INTO public.notifications (user_id, type, title, message, data) VALUES (
      v_referrer.id, 'referral_success', 'Nouveau filleul !',
      format('%s a rejoint Wakati avec ton code. +%s %s crédités !', v_clean_username, v_bonus_referrer, v_bonus_asset),
      jsonb_build_object('referred_user_id', p_user_id, 'referred_username', v_clean_username, 'bonus_amount', v_bonus_referrer)
    );

    INSERT INTO public.notifications (user_id, type, title, message, data) VALUES (
      p_user_id, 'referral_bonus', 'Code referral appliqué !',
      format('+%s %s crédités grâce au code de %s', v_bonus_referred, v_bonus_asset, v_referrer_username),
      jsonb_build_object('referrer_id', v_referrer.id, 'referrer_username', v_referrer_username, 'bonus_amount', v_bonus_referred)
    );

  END IF;

  UPDATE public.users
  SET username = v_clean_username, profile_completed = true, updated_at = NOW()
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'success',           true,
    'username',          v_clean_username,
    'profile_completed', true,
    'referral_applied',  v_referral_applied,
    'referrer_username', v_referrer_username,
    'bonus_amount',      CASE WHEN v_referral_applied THEN v_bonus_referred ELSE 0 END,
    'bonus_asset',       v_bonus_asset,
    'message',           CASE
                           WHEN v_referral_applied
                           THEN format('Bienvenue ! +%s %s crédités.', v_bonus_referred, v_bonus_asset)
                           ELSE 'Profil complété avec succès.'
                         END
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', 'INTERNAL_ERROR', 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_campay_deposit(p_external_reference text, p_campay_tx_id text, p_amount numeric, p_fee numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_user_id uuid;
  v_net_amount numeric;
BEGIN
  SELECT id, user_id, (amount - COALESCE(fee, 0))
  INTO v_tx_id, v_user_id, v_net_amount
  FROM transactions
  WHERE metadata->>'external_reference' = p_external_reference
    AND type = 'deposit'
    AND status IN ('pending', 'processing')
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable ou déjà traitée');
  END IF;

  UPDATE transactions
  SET status = 'completed', tx_hash = p_campay_tx_id, completed_at = now(),
      metadata = metadata || jsonb_build_object('campay_tx_id', p_campay_tx_id, 'callback_received_at', now())
  WHERE id = v_tx_id;

  PERFORM increment_balance(v_user_id, 'FCFA', v_net_amount);

  IF p_fee > 0 THEN
    PERFORM collect_fee_to_platform('FCFA', p_fee, 'deposit_fee', v_user_id, v_tx_id);
  END IF;

  UPDATE user_transaction_limits
  SET daily_deposit_used = daily_deposit_used + p_amount, updated_at = now()
  WHERE user_id = v_user_id;

  INSERT INTO notifications (user_id, type, title, message, data)
  VALUES (v_user_id, 'deposit_confirmed', 'Dépôt confirmé ✅',
    format('Votre dépôt de %s FCFA a été crédité sur votre compte.', v_net_amount),
    jsonb_build_object('transaction_id', v_tx_id, 'amount', v_net_amount, 'tran_id', p_campay_tx_id));

  PERFORM fn_award_engagement_points(v_user_id, 'deposit');

  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id, 'user_id', v_user_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_mobile_money_deposit(p_external_reference text, p_provider_tx_id text, p_amount numeric, p_fee numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_user_id uuid;
  v_asset_symbol text;
  v_net_amount numeric;
BEGIN
  -- FOR UPDATE : verrouille la ligne de transaction jusqu'a la fin de la
  -- transaction Postgres. Si deux webhooks du provider arrivent en meme temps
  -- (retry sur timeout, tres courant), le second attend ici puis relit le
  -- statut deja passe a 'completed' par le premier -> NOT FOUND -> pas de
  -- double credit. Sans ce verrou, les deux peuvent lire 'pending' simultanement.
  SELECT id, user_id, asset_symbol, (amount - COALESCE(fee, 0))
  INTO v_tx_id, v_user_id, v_asset_symbol, v_net_amount
  FROM transactions
  WHERE metadata->>'external_reference' = p_external_reference
    AND type = 'deposit'
    AND status IN ('pending', 'processing')
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable ou déjà traitée');
  END IF;

  UPDATE transactions
  SET status = 'completed', tx_hash = p_provider_tx_id, completed_at = now(),
      metadata = metadata || jsonb_build_object('provider_tx_id', p_provider_tx_id, 'callback_received_at', now())
  WHERE id = v_tx_id;

  PERFORM increment_balance(v_user_id, v_asset_symbol, v_net_amount);

  IF p_fee > 0 THEN
    PERFORM collect_fee_to_platform(v_asset_symbol, p_fee, 'deposit_fee', v_user_id, v_tx_id);
  END IF;

  UPDATE user_transaction_limits
  SET daily_deposit_used = daily_deposit_used + p_amount, updated_at = now()
  WHERE user_id = v_user_id;

  INSERT INTO notifications (user_id, type, title, message, data)
  VALUES (v_user_id, 'deposit_confirmed', 'Dépôt confirmé ✅',
    format('Votre dépôt de %s %s a été crédité sur votre compte.', v_net_amount, v_asset_symbol),
    jsonb_build_object('transaction_id', v_tx_id, 'amount', v_net_amount, 'tran_id', p_provider_tx_id));

  PERFORM fn_award_engagement_points(v_user_id, 'deposit');

  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id, 'user_id', v_user_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_mobile_money_withdrawal(p_external_reference text, p_provider_tx_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_user_id uuid;
  v_net_amount numeric;
  v_asset text;
BEGIN
  SELECT id, user_id, net_amount, asset_symbol INTO v_tx_id, v_user_id, v_net_amount, v_asset
  FROM transactions
  WHERE metadata->>'external_reference' = p_external_reference
    AND type = 'withdrawal' AND status IN ('pending', 'processing')
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable ou deja traitee');
  END IF;

  UPDATE transactions
  SET status = 'completed', completed_at = now(),
      metadata = metadata || jsonb_build_object('provider_tx_id', p_provider_tx_id)
  WHERE id = v_tx_id;

  INSERT INTO notifications (user_id, type, title, message, data)
  VALUES (
    v_user_id, 'withdrawal_completed', 'Retrait effectué ✅',
    format('Votre retrait de %s %s a été envoyé avec succès.', v_net_amount, v_asset),
    jsonb_build_object('amount', v_net_amount)
  );

  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.decrement_balance(p_user_id uuid, p_asset_symbol text, p_amount numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_balance numeric;
BEGIN
  -- Réservé aux rôles internes uniquement
  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'decrement_balance: accès non autorisé (rôle: %)', current_role
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Validation du montant
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'decrement_balance: le montant doit être positif (reçu: %)', p_amount
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE user_balances
  SET available_balance = available_balance - p_amount,
      updated_at = now()
  WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol
  RETURNING available_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'decrement_balance: aucun solde trouvé pour user_id=% asset=%', p_user_id, p_asset_symbol
      USING ERRCODE = 'no_data_found';
  END IF;

  -- Vérification solde négatif (filet de sécurité)
  IF new_balance < 0 THEN
    RAISE EXCEPTION 'decrement_balance: solde insuffisant pour user_id=% asset=% (nouveau solde: %)', 
      p_user_id, p_asset_symbol, new_balance
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN new_balance;
END;
$function$

CREATE OR REPLACE FUNCTION public.distribute_staking_rewards()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_apr        numeric;
  v_daily_rate numeric;
  v_count      int := 0;
  v_total_dist numeric := 0;
BEGIN
  SELECT apr INTO v_apr FROM staking_config WHERE id = 1;
  IF v_apr IS NULL OR v_apr <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'APR non configuré');
  END IF;

  v_daily_rate := v_apr / 100.0 / 365.0;

  SELECT COALESCE(SUM(amount * v_daily_rate), 0) INTO v_total_dist
  FROM user_stakes
  WHERE status = 'active'
    AND pool_id = 'f6c208e1-f277-4720-b303-45c1b607bf1f';

  UPDATE user_stakes SET
    pending_rewards         = pending_rewards + (amount * v_daily_rate),
    last_reward_calculation = now(),
    updated_at              = now()
  WHERE status  = 'active'
    AND pool_id = 'f6c208e1-f277-4720-b303-45c1b607bf1f';

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'stakers_updated', v_count,
    'apr_used', v_apr,
    'total_distributed_today', ROUND(v_total_dist, 8)
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.estimate_swap(p_from_asset text, p_to_asset text, p_amount numeric, p_fee_rate numeric DEFAULT NULL::numeric)
 RETURNS TABLE(from_asset text, to_asset text, amount_in numeric, amount_out numeric, gross_out numeric, rate numeric, fee_amount numeric, fee_rate_pct numeric, price_impact text, is_valid boolean, error_message text)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_price_from numeric;
    v_price_to   numeric;
    v_rate       numeric;
    v_gross_out  numeric;
    v_fee        numeric;
    v_net_out    numeric;
    v_actual_fee_rate numeric;
    v_from_asset_record record;
    v_to_asset_record record;
BEGIN
    -- Récupérer les informations des assets source et destination
    SELECT * INTO v_from_asset_record 
    FROM public.supported_assets 
    WHERE symbol = p_from_asset AND is_active = true;
    
    SELECT * INTO v_to_asset_record 
    FROM public.supported_assets 
    WHERE symbol = p_to_asset AND is_active = true;
    
    -- Vérifier que les assets existent et sont actifs
    IF v_from_asset_record IS NULL THEN
        RETURN QUERY SELECT
            p_from_asset, p_to_asset, p_amount,
            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
            'Asset source non trouvé ou inactif'::text,
            false, 'Asset source invalide'::text;
        RETURN;
    END IF;
    
    IF v_to_asset_record IS NULL THEN
        RETURN QUERY SELECT
            p_from_asset, p_to_asset, p_amount,
            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
            'Asset destination non trouvé ou inactif'::text,
            false, 'Asset destination invalide'::text;
        RETURN;
    END IF;
    
    -- Vérifier que les assets peuvent être swappés
    IF NOT v_from_asset_record.can_be_swapped THEN
        RETURN QUERY SELECT
            p_from_asset, p_to_asset, p_amount,
            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
            'Swap non autorisé pour l''asset source'::text,
            false, 'Swap non autorisé'::text;
        RETURN;
    END IF;
    
    IF NOT v_to_asset_record.can_be_swapped THEN
        RETURN QUERY SELECT
            p_from_asset, p_to_asset, p_amount,
            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
            'Swap non autorisé pour l''asset destination'::text,
            false, 'Swap non autorisé'::text;
        RETURN;
    END IF;
    
    -- Récupérer les prix depuis asset_prices
    SELECT price_usd INTO v_price_from 
    FROM public.asset_prices 
    WHERE asset_symbol = p_from_asset;
    
    SELECT price_usd INTO v_price_to 
    FROM public.asset_prices 
    WHERE asset_symbol = p_to_asset;

    -- Vérifier que les prix sont disponibles
    IF v_price_from IS NULL OR v_price_from = 0 THEN
        RETURN QUERY SELECT
            p_from_asset, p_to_asset, p_amount,
            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
            'Prix non disponible pour ' || p_from_asset,
            false, 'Prix non disponible'::text;
        RETURN;
    END IF;
    
    IF v_price_to IS NULL OR v_price_to = 0 THEN
        RETURN QUERY SELECT
            p_from_asset, p_to_asset, p_amount,
            0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
            'Prix non disponible pour ' || p_to_asset,
            false, 'Prix non disponible'::text;
        RETURN;
    END IF;
    
    -- ✅ Déterminer le taux de frais à utiliser
    -- Priorité: paramètre fourni → swap_fee_percentage de l'asset source → 0.5% par défaut
    v_actual_fee_rate := COALESCE(
        p_fee_rate, 
        v_from_asset_record.swap_fee_percentage, 
        0.5  -- 0.5% par défaut si rien n'est configuré
    );
    
    -- Calculer le taux de change et les montants
    v_rate      := v_price_from / v_price_to;
    v_gross_out := p_amount * v_rate;
    v_fee       := v_gross_out * (v_actual_fee_rate / 100);  -- Conversion pourcentage → décimal
    v_net_out   := v_gross_out - v_fee;

    -- Retourner le résultat
    RETURN QUERY SELECT
        p_from_asset,
        p_to_asset,
        p_amount,
        ROUND(v_net_out, 8),
        ROUND(v_gross_out, 8),
        ROUND(v_rate, 6),
        ROUND(v_fee, 8),
        ROUND(v_actual_fee_rate, 2),  -- Retourne le pourcentage
        'Faible'::text,
        true,
        NULL::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_swap_realtime(p_user_id uuid, p_from_asset text, p_to_asset text, p_from_amount numeric, p_slippage_tolerance numeric DEFAULT 1.0)
 RETURNS TABLE(success boolean, message text, transaction_id uuid, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, net_to_amount numeric, realtime_price_used boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_estimate record;
    v_user_balance numeric;
    v_transaction_id uuid;
    v_swap_tx_id uuid;
    v_from_asset_record record;
    v_to_asset_record record;
    v_fee_rate numeric;
    v_treasury_to_balance numeric;
BEGIN
    IF p_from_asset = p_to_asset THEN
        RETURN QUERY SELECT
            FALSE, 'Impossible de swapper le même asset',
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    IF p_from_amount <= 0 THEN
        RETURN QUERY SELECT
            FALSE, 'Le montant doit être supérieur à 0',
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    SELECT * INTO v_from_asset_record
    FROM public.supported_assets
    WHERE symbol = p_from_asset AND is_active = true AND can_be_swapped = true;

    SELECT * INTO v_to_asset_record
    FROM public.supported_assets
    WHERE symbol = p_to_asset AND is_active = true AND can_be_swapped = true;

    IF v_from_asset_record IS NULL THEN
        RETURN QUERY SELECT
            FALSE, format('Swap non autorisé pour l''asset source: %s', p_from_asset),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    IF v_to_asset_record IS NULL THEN
        RETURN QUERY SELECT
            FALSE, format('Swap non autorisé pour l''asset destination: %s', p_to_asset),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    v_fee_rate := COALESCE(v_from_asset_record.swap_fee_percentage, 0.5);

    SELECT * INTO v_estimate
    FROM public.estimate_swap(p_from_asset, p_to_asset, p_from_amount, v_fee_rate);

    IF v_estimate.amount_out IS NULL OR v_estimate.amount_out <= 0 THEN
        RETURN QUERY SELECT
            FALSE, 'Impossible d''estimer le swap',
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    SELECT available_balance INTO v_user_balance
    FROM public.user_balances
    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;

    IF v_user_balance IS NULL OR v_user_balance < p_from_amount THEN
        RETURN QUERY SELECT
            FALSE,
            format('Solde insuffisant en %s. Disponible: %s, Requis: %s',
                   p_from_asset, COALESCE(v_user_balance, 0), p_from_amount),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    -- ✅ CONSERVATION : la trésorerie doit réellement détenir l'actif de
    -- destination avant qu'on promette quoi que ce soit à l'utilisateur.
    SELECT balance INTO v_treasury_to_balance
    FROM public.treasury_wallets WHERE asset_symbol = p_to_asset FOR UPDATE;

    IF v_treasury_to_balance IS NULL OR v_treasury_to_balance < v_estimate.amount_out THEN
        RETURN QUERY SELECT
            FALSE,
            format('Réserve de liquidité insuffisante en %s pour ce swap. Réessayez avec un montant plus petit ou plus tard.', p_to_asset),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    INSERT INTO public.transactions (
        user_id, type, asset_symbol, network, amount, status, metadata
    ) VALUES (
        p_user_id, 'swap_debit', p_from_asset, v_from_asset_record.network, p_from_amount, 'completed',
        jsonb_build_object(
            'swap_type', 'asset_swap', 'to_asset', p_to_asset, 'exchange_rate', v_estimate.rate,
            'fee_percentage', v_fee_rate, 'slippage_tolerance', p_slippage_tolerance
        )
    ) RETURNING id INTO v_swap_tx_id;

    UPDATE public.user_balances
    SET available_balance = available_balance - p_from_amount, updated_at = NOW()
    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;

    -- ✅ La trésorerie REÇOIT ce que l'utilisateur donne (jambe source).
    INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected, total_burned, total_withdrawn, updated_at)
    VALUES (p_from_asset, p_from_amount, p_from_amount, 0, 0, NOW())
    ON CONFLICT (asset_symbol) DO UPDATE
    SET balance = treasury_wallets.balance + p_from_amount,
        total_collected = treasury_wallets.total_collected + p_from_amount,
        updated_at = NOW();

    -- ✅ La trésorerie DONNE ce qu'elle doit à l'utilisateur (jambe destination).
    UPDATE public.treasury_wallets
    SET balance = balance - v_estimate.amount_out, updated_at = NOW()
    WHERE asset_symbol = p_to_asset;

    INSERT INTO public.transactions (
        user_id, type, asset_symbol, network, amount, fee, net_amount, status, reference_id, metadata
    ) VALUES (
        p_user_id, 'swap_credit', p_to_asset, v_to_asset_record.network, v_estimate.amount_out,
        v_estimate.fee_amount, v_estimate.amount_out, 'completed', v_swap_tx_id,
        jsonb_build_object('swap_type', 'asset_swap', 'from_asset', p_from_asset, 'from_amount', p_from_amount, 'exchange_rate', v_estimate.rate)
    ) RETURNING id INTO v_transaction_id;

    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)
    VALUES (p_user_id, p_to_asset, v_estimate.amount_out)
    ON CONFLICT (user_id, asset_symbol)
    DO UPDATE SET available_balance = user_balances.available_balance + v_estimate.amount_out, updated_at = NOW();

    -- ✅ Trace de revenu réel pour les calculs de capacité de crédit et de
    -- prix WAKATI (audit uniquement : l'argent a déjà bougé ci-dessus via
    -- les 2 jambes, ceci ne fait que l'enregistrer comme revenu).
    IF v_estimate.fee_amount > 0 THEN
      INSERT INTO public.platform_fees (asset_symbol, amount, fee_type, source_user_id, source_transaction_id, collected_at)
      VALUES (p_to_asset, v_estimate.fee_amount, 'swap_fee', p_user_id, v_transaction_id, NOW());
    END IF;

    UPDATE public.supported_assets_metrics
    SET total_swap_volume = COALESCE(total_swap_volume, 0) + p_from_amount,
        total_swap_fees_collected = COALESCE(total_swap_fees_collected, 0) + v_estimate.fee_amount,
        total_fees_collected = COALESCE(total_fees_collected, 0) + v_estimate.fee_amount,
        last_updated = NOW()
    WHERE asset_symbol = p_from_asset;

    IF NOT FOUND THEN
        INSERT INTO public.supported_assets_metrics (
            asset_symbol, total_swap_volume, total_swap_fees_collected, total_fees_collected,
            total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated
        ) VALUES (p_from_asset, p_from_amount, v_estimate.fee_amount, v_estimate.fee_amount, 0, 0, 0, 0, 0, 0, NOW());
    END IF;

    UPDATE public.supported_assets_metrics
    SET total_swap_volume = COALESCE(total_swap_volume, 0) + v_estimate.amount_out, last_updated = NOW()
    WHERE asset_symbol = p_to_asset;

    IF NOT FOUND THEN
        INSERT INTO public.supported_assets_metrics (
            asset_symbol, total_swap_volume, total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated
        ) VALUES (p_to_asset, v_estimate.amount_out, 0, 0, 0, 0, 0, 0, NOW());
    END IF;

    PERFORM fn_award_engagement_points(p_user_id, 'swap');

    RETURN QUERY SELECT
        TRUE,
        format('Swap réussi! %s %s → %s %s (frais: %s %s)',
               p_from_amount, p_from_asset, v_estimate.amount_out, p_to_asset, v_estimate.fee_amount, p_to_asset),
        v_transaction_id, p_from_amount, v_estimate.amount_out, v_estimate.rate, v_estimate.fee_amount, v_estimate.amount_out, true;

EXCEPTION
    WHEN OTHERS THEN
        RETURN QUERY SELECT FALSE, 'Erreur lors du swap: ' || SQLERRM, NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_swap_realtime(p_user_id uuid, p_from_asset text, p_to_asset text, p_from_amount numeric, p_slippage_tolerance numeric DEFAULT 1.0, p_min_amount_out numeric DEFAULT NULL::numeric)
 RETURNS TABLE(success boolean, message text, transaction_id uuid, from_amount numeric, to_amount numeric, exchange_rate numeric, fee_amount numeric, net_to_amount numeric, realtime_price_used boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_estimate record;
    v_user_balance numeric;
    v_transaction_id uuid;
    v_swap_tx_id uuid;
    v_from_asset_record record;
    v_to_asset_record record;
    v_fee_rate numeric;
    v_treasury_to_balance numeric;
BEGIN
    IF p_from_asset = p_to_asset THEN
        RETURN QUERY SELECT
            FALSE, 'Impossible de swapper le même asset',
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    IF p_from_amount <= 0 THEN
        RETURN QUERY SELECT
            FALSE, 'Le montant doit être supérieur à 0',
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    SELECT * INTO v_from_asset_record
    FROM public.supported_assets
    WHERE symbol = p_from_asset AND is_active = true AND can_be_swapped = true;

    SELECT * INTO v_to_asset_record
    FROM public.supported_assets
    WHERE symbol = p_to_asset AND is_active = true AND can_be_swapped = true;

    IF v_from_asset_record IS NULL THEN
        RETURN QUERY SELECT
            FALSE, format('Swap non autorisé pour l''asset source: %s', p_from_asset),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    IF v_to_asset_record IS NULL THEN
        RETURN QUERY SELECT
            FALSE, format('Swap non autorisé pour l''asset destination: %s', p_to_asset),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    v_fee_rate := COALESCE(v_from_asset_record.swap_fee_percentage, 0.5);

    SELECT * INTO v_estimate
    FROM public.estimate_swap(p_from_asset, p_to_asset, p_from_amount, v_fee_rate);

    IF v_estimate.amount_out IS NULL OR v_estimate.amount_out <= 0 THEN
        RETURN QUERY SELECT
            FALSE, 'Impossible d''estimer le swap',
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    -- ✅ PROTECTION ANTI-SLIPPAGE : si l'appelant a fourni le montant minimum
    -- accepté (calculé au moment du devis affiché), on refuse le swap si le
    -- taux a bougé en dessous de ce seuil entre le devis et l'exécution.
    IF p_min_amount_out IS NOT NULL AND v_estimate.amount_out < p_min_amount_out THEN
        RETURN QUERY SELECT
            FALSE,
            format('Le taux a changé : %s %s reçus au lieu du minimum accepté de %s %s. Merci de reconfirmer.',
                   v_estimate.amount_out, p_to_asset, p_min_amount_out, p_to_asset),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    SELECT available_balance INTO v_user_balance
    FROM public.user_balances
    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;

    IF v_user_balance IS NULL OR v_user_balance < p_from_amount THEN
        RETURN QUERY SELECT
            FALSE,
            format('Solde insuffisant en %s. Disponible: %s, Requis: %s',
                   p_from_asset, COALESCE(v_user_balance, 0), p_from_amount),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    SELECT balance INTO v_treasury_to_balance
    FROM public.treasury_wallets WHERE asset_symbol = p_to_asset FOR UPDATE;

    IF v_treasury_to_balance IS NULL OR v_treasury_to_balance < v_estimate.amount_out THEN
        RETURN QUERY SELECT
            FALSE,
            format('Réserve de liquidité insuffisante en %s pour ce swap. Réessayez avec un montant plus petit ou plus tard.', p_to_asset),
            NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
        RETURN;
    END IF;

    INSERT INTO public.transactions (
        user_id, type, asset_symbol, network, amount, status, metadata
    ) VALUES (
        p_user_id, 'swap_debit', p_from_asset, v_from_asset_record.network, p_from_amount, 'completed',
        jsonb_build_object(
            'swap_type', 'asset_swap', 'to_asset', p_to_asset, 'exchange_rate', v_estimate.rate,
            'fee_percentage', v_fee_rate, 'slippage_tolerance', p_slippage_tolerance,
            'min_amount_out', p_min_amount_out
        )
    ) RETURNING id INTO v_swap_tx_id;

    UPDATE public.user_balances
    SET available_balance = available_balance - p_from_amount, updated_at = NOW()
    WHERE user_id = p_user_id AND asset_symbol = p_from_asset;

    INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected, total_burned, total_withdrawn, updated_at)
    VALUES (p_from_asset, p_from_amount, p_from_amount, 0, 0, NOW())
    ON CONFLICT (asset_symbol) DO UPDATE
    SET balance = treasury_wallets.balance + p_from_amount,
        total_collected = treasury_wallets.total_collected + p_from_amount,
        updated_at = NOW();

    UPDATE public.treasury_wallets
    SET balance = balance - v_estimate.amount_out, updated_at = NOW()
    WHERE asset_symbol = p_to_asset;

    INSERT INTO public.transactions (
        user_id, type, asset_symbol, network, amount, fee, net_amount, status, reference_id, metadata
    ) VALUES (
        p_user_id, 'swap_credit', p_to_asset, v_to_asset_record.network, v_estimate.amount_out,
        v_estimate.fee_amount, v_estimate.amount_out, 'completed', v_swap_tx_id,
        jsonb_build_object('swap_type', 'asset_swap', 'from_asset', p_from_asset, 'from_amount', p_from_amount, 'exchange_rate', v_estimate.rate)
    ) RETURNING id INTO v_transaction_id;

    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)
    VALUES (p_user_id, p_to_asset, v_estimate.amount_out)
    ON CONFLICT (user_id, asset_symbol)
    DO UPDATE SET available_balance = user_balances.available_balance + v_estimate.amount_out, updated_at = NOW();

    IF v_estimate.fee_amount > 0 THEN
      INSERT INTO public.platform_fees (asset_symbol, amount, fee_type, source_user_id, source_transaction_id, collected_at)
      VALUES (p_to_asset, v_estimate.fee_amount, 'swap_fee', p_user_id, v_transaction_id, NOW());
    END IF;

    UPDATE public.supported_assets_metrics
    SET total_swap_volume = COALESCE(total_swap_volume, 0) + p_from_amount,
        total_swap_fees_collected = COALESCE(total_swap_fees_collected, 0) + v_estimate.fee_amount,
        total_fees_collected = COALESCE(total_fees_collected, 0) + v_estimate.fee_amount,
        last_updated = NOW()
    WHERE asset_symbol = p_from_asset;

    IF NOT FOUND THEN
        INSERT INTO public.supported_assets_metrics (
            asset_symbol, total_swap_volume, total_swap_fees_collected, total_fees_collected,
            total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated
        ) VALUES (p_from_asset, p_from_amount, v_estimate.fee_amount, v_estimate.fee_amount, 0, 0, 0, 0, 0, 0, NOW());
    END IF;

    UPDATE public.supported_assets_metrics
    SET total_swap_volume = COALESCE(total_swap_volume, 0) + v_estimate.amount_out, last_updated = NOW()
    WHERE asset_symbol = p_to_asset;

    IF NOT FOUND THEN
        INSERT INTO public.supported_assets_metrics (
            asset_symbol, total_swap_volume, total_deposited, total_withdrawn, total_staked, total_user_balance, net_position, should_be_in_custody, last_updated
        ) VALUES (p_to_asset, v_estimate.amount_out, 0, 0, 0, 0, 0, 0, NOW());
    END IF;

    PERFORM fn_award_engagement_points(p_user_id, 'swap');

    RETURN QUERY SELECT
        TRUE,
        format('Swap réussi! %s %s → %s %s (frais: %s %s)',
               p_from_amount, p_from_asset, v_estimate.amount_out, p_to_asset, v_estimate.fee_amount, p_to_asset),
        v_transaction_id, p_from_amount, v_estimate.amount_out, v_estimate.rate, v_estimate.fee_amount, v_estimate.amount_out, true;

EXCEPTION
    WHEN OTHERS THEN
        RETURN QUERY SELECT FALSE, 'Erreur lors du swap: ' || SQLERRM, NULL::uuid, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_wheel_spin(p_user_id uuid, p_spin_type text, p_segment_id integer, p_spin_hash text, p_client_seed text, p_server_seed text, p_nonce integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config       RECORD;
  v_stats        RECORD;
  v_segment      RECORD;
  v_now          TIMESTAMPTZ := NOW();
  v_today        DATE        := CURRENT_DATE;
  v_spin_cost    NUMERIC     := 0;
  v_spin_asset   TEXT;
  v_jackpot_cut  NUMERIC     := 0;
  v_house_cut    NUMERIC     := 0;
  v_new_streak   INT;
  v_streak_bonus INT         := 0;
  v_daily        INTEGER;
  -- ✅ Suivi de la perte nette pour le signal de crédit (score_credit_capacity)
  v_payout_asset     TEXT;
  v_payout_amount    NUMERIC := 0;
  v_spin_price_usd   NUMERIC;
  v_payout_price_usd NUMERIC;
  v_net_loss_usd     NUMERIC;
  v_net_loss_native  NUMERIC;
BEGIN
  SELECT * INTO v_config  FROM public.wheel_config     WHERE id = 1              FOR UPDATE;
  SELECT * INTO v_stats   FROM public.user_wheel_stats WHERE user_id = p_user_id FOR UPDATE;
  SELECT * INTO v_segment FROM public.wheel_segments   WHERE id = p_segment_id AND is_active = true;

  v_spin_asset := v_config.paid_spin_cost_asset;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Segment invalide', 'error_code', 'INVALID_SEGMENT');
  END IF;
  IF NOT v_config.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'Roue désactivée', 'error_code', 'WHEEL_DISABLED');
  END IF;

  IF p_spin_type = 'free' THEN

    IF v_stats.free_spins_reset_at <= v_now THEN
      v_daily := CASE WHEN public.fn_user_can_get_free_spins(p_user_id)
                       THEN v_config.free_spins_daily ELSE 0 END;
      UPDATE public.user_wheel_stats
      SET free_spins_remaining = v_daily,
          free_spins_reset_at  = date_trunc('day', v_now) + INTERVAL '1 day'
      WHERE user_id = p_user_id;
      v_stats.free_spins_remaining := v_daily;
    END IF;

    IF v_stats.free_spins_remaining <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'Aucun spin gratuit disponible', 'error_code', 'NO_FREE_SPINS');
    END IF;

    UPDATE public.user_wheel_stats
    SET free_spins_remaining  = free_spins_remaining - 1,
        total_free_spins_used = total_free_spins_used + 1
    WHERE user_id = p_user_id;

  ELSIF p_spin_type = 'paid' THEN
    v_spin_cost   := v_config.paid_spin_cost_amount;
    v_jackpot_cut := ROUND(v_spin_cost * v_config.jackpot_contribution_pct / 100, 8);
    v_house_cut   := v_spin_cost - v_jackpot_cut;

    IF NOT EXISTS (
      SELECT 1 FROM public.user_balances
      WHERE user_id = p_user_id AND asset_symbol = v_spin_asset
        AND available_balance >= v_spin_cost
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Solde ' || v_spin_asset || ' insuffisant', 'error_code', 'INSUFFICIENT_BALANCE');
    END IF;

    UPDATE public.user_balances
    SET available_balance = available_balance - v_spin_cost,
        updated_at        = v_now
    WHERE user_id = p_user_id AND asset_symbol = v_spin_asset;

    UPDATE public.wheel_config
    SET jackpot_current_amount = jackpot_current_amount + v_jackpot_cut,
        updated_at             = v_now
    WHERE id = 1;

    -- Comptabilité de trésorerie réelle : INCHANGÉE. Le coût brut du spin
    -- (moins la part jackpot) est bien physiquement encaissé, peu importe
    -- ce qui se passe ensuite avec la récompense.
    IF v_house_cut > 0 THEN
      PERFORM collect_fee_to_platform(v_spin_asset, v_house_cut, 'game_house_edge', p_user_id, NULL);
    END IF;

    INSERT INTO public.transactions (
      user_id, type, asset_symbol, amount, status, metadata, created_at
    ) VALUES (
      p_user_id, 'game_bet', v_spin_asset, v_spin_cost, 'completed',
      jsonb_build_object('spin_hash', p_spin_hash, 'spin_type', 'paid', 'game_type', 'wheel'),
      v_now
    );

    UPDATE public.user_wheel_stats
    SET total_paid_spins_used = total_paid_spins_used + 1,
        total_wakati_spent    = total_wakati_spent + v_spin_cost
    WHERE user_id = p_user_id;

    PERFORM fn_award_engagement_points(p_user_id, 'wheel_paid');

  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Type de spin invalide', 'error_code', 'INVALID_SPIN_TYPE');
  END IF;

  IF    v_stats.last_spin_date IS NULL                               THEN v_new_streak := 1;
  ELSIF v_stats.last_spin_date = v_today                             THEN v_new_streak := v_stats.current_streak;
  ELSIF v_stats.last_spin_date = v_today - INTERVAL '1 day'          THEN v_new_streak := v_stats.current_streak + 1;
  ELSE                                                                     v_new_streak := 1;
  END IF;

  IF v_new_streak > v_stats.current_streak
    AND v_config.streak_bonus_interval > 0
    AND v_new_streak % v_config.streak_bonus_interval = 0 THEN
    v_streak_bonus := v_config.streak_bonus_free_spins;
  END IF;

  IF v_segment.is_jackpot THEN
    DECLARE v_jackpot_amount NUMERIC;
    BEGIN
      SELECT jackpot_current_amount INTO v_jackpot_amount FROM public.wheel_config WHERE id = 1;
      IF v_jackpot_amount > 0 THEN
        INSERT INTO public.user_balances (user_id, asset_symbol, available_balance, updated_at)
        VALUES (p_user_id, v_config.jackpot_asset_symbol, v_jackpot_amount, v_now)
        ON CONFLICT (user_id, asset_symbol) DO UPDATE
        SET available_balance = user_balances.available_balance + v_jackpot_amount, updated_at = v_now;

        UPDATE public.wheel_config SET jackpot_current_amount = 0, updated_at = v_now WHERE id = 1;

        INSERT INTO public.transactions (
          user_id, type, asset_symbol, amount, status, metadata, created_at
        ) VALUES (
          p_user_id, 'game_win', v_config.jackpot_asset_symbol, v_jackpot_amount, 'completed',
          jsonb_build_object('spin_hash', p_spin_hash, 'game_type', 'wheel', 'reward_type', 'jackpot'),
          v_now
        );

        -- ✅ Payout suivi pour le calcul de perte nette (crédit)
        v_payout_asset  := v_config.jackpot_asset_symbol;
        v_payout_amount := v_jackpot_amount;
      END IF;
    END;

  ELSIF v_segment.reward_type = 'free_spins' THEN
    UPDATE public.user_wheel_stats
    SET free_spins_remaining = free_spins_remaining + COALESCE(v_segment.free_spins_reward, 0)
    WHERE user_id = p_user_id;
    -- Pas de valeur monétaire : ne compte pas comme un gain qui réduit la perte nette.

  ELSIF COALESCE(v_segment.reward_amount, 0) > 0 THEN
    DECLARE
      v_reward_amount NUMERIC;
      v_reward_asset  TEXT;
    BEGIN
      v_reward_asset  := COALESCE(v_segment.asset_symbol, v_spin_asset);
      v_reward_amount := CASE v_segment.reward_type
        WHEN 'fixed_amount'   THEN v_segment.reward_amount
        WHEN 'multiplier'     THEN v_spin_cost * v_segment.multiplier_value
        WHEN 'bet_multiplier' THEN v_spin_cost * v_segment.reward_amount
        ELSE 0
      END;

      IF v_reward_amount > 0 THEN
        INSERT INTO public.user_balances (user_id, asset_symbol, available_balance, updated_at)
        VALUES (p_user_id, v_reward_asset, v_reward_amount, v_now)
        ON CONFLICT (user_id, asset_symbol) DO UPDATE
        SET available_balance = user_balances.available_balance + v_reward_amount, updated_at = v_now;

        PERFORM fn_treasury_debit_for_payout(
          v_reward_asset, v_reward_amount, p_user_id, 'Recompense roue segment ' || p_segment_id::text
        );

        INSERT INTO public.transactions (
          user_id, type, asset_symbol, amount, status, metadata, created_at
        ) VALUES (
          p_user_id, 'game_win', v_reward_asset, v_reward_amount, 'completed',
          jsonb_build_object('spin_hash', p_spin_hash, 'segment_id', p_segment_id,
                              'game_type', 'wheel', 'reward_type', v_segment.reward_type),
          v_now
        );

        -- ✅ Payout suivi pour le calcul de perte nette (crédit)
        v_payout_asset  := v_reward_asset;
        v_payout_amount := v_reward_amount;
      END IF;
    END;
  END IF;

  -- ══════════════════════════════════════════════════════════════════════
  -- ✅ SIGNAL DE CRÉDIT : perte nette réelle du spin payant (spin_cost -
  -- récompense payée sur CE spin), jamais négative. N'affecte QUE le calcul
  -- de capacité d'emprunt (fn_score_credit_capacity), pas la trésorerie.
  -- ══════════════════════════════════════════════════════════════════════
  IF p_spin_type = 'paid' AND v_spin_cost > 0 THEN
    SELECT price_usd INTO v_spin_price_usd FROM public.asset_prices WHERE asset_symbol = v_spin_asset;
    v_spin_price_usd := COALESCE(v_spin_price_usd, 0);

    IF v_payout_amount > 0 AND v_payout_asset IS NOT NULL THEN
      SELECT price_usd INTO v_payout_price_usd FROM public.asset_prices WHERE asset_symbol = v_payout_asset;
      v_payout_price_usd := COALESCE(v_payout_price_usd, 0);
    ELSE
      v_payout_price_usd := 0;
    END IF;

    IF v_spin_price_usd > 0 THEN
      v_net_loss_usd := GREATEST(v_spin_cost * v_spin_price_usd - v_payout_amount * v_payout_price_usd, 0);

      IF v_net_loss_usd > 0 THEN
        v_net_loss_native := v_net_loss_usd / v_spin_price_usd;

        INSERT INTO public.platform_fees (asset_symbol, amount, fee_type, source_user_id, collected_at)
        VALUES (v_spin_asset, v_net_loss_native, 'game_net_loss', p_user_id, v_now);
      END IF;
    END IF;
  END IF;

  UPDATE public.user_wheel_stats
  SET current_streak       = v_new_streak,
      longest_streak       = GREATEST(longest_streak, v_new_streak),
      last_spin_date       = v_today,
      total_spins          = total_spins + 1,
      free_spins_remaining = free_spins_remaining + v_streak_bonus,
      updated_at           = v_now
  WHERE user_id = p_user_id;

  INSERT INTO public.wheel_spins (
    user_id, segment_id, bet_amount, bet_asset,
    reward_amount, reward_asset, final_reward_amount,
    client_seed, server_seed, nonce, spin_hash, spin_result
  ) VALUES (
    p_user_id, p_segment_id,
    CASE WHEN p_spin_type = 'paid' THEN v_spin_cost ELSE 0 END,
    CASE WHEN p_spin_type = 'paid' THEN v_spin_asset ELSE NULL END,
    COALESCE(v_segment.reward_amount, 0), v_segment.asset_symbol, COALESCE(v_segment.reward_amount, 0),
    p_client_seed, p_server_seed, p_nonce, p_spin_hash,
    jsonb_build_object('spin_type', p_spin_type, 'segment', row_to_json(v_segment))
  );

  RETURN jsonb_build_object(
    'success',           true,
    'segment_id',        v_segment.id,
    'segment_label',     v_segment.label,
    'reward_type',       v_segment.reward_type,
    'reward_amount',     COALESCE(v_segment.reward_amount, 0),
    'reward_asset',      v_segment.asset_symbol,
    'is_jackpot',        COALESCE(v_segment.is_jackpot, false),
    'free_spins_reward', COALESCE(v_segment.free_spins_reward, 0),
    'streak',            v_new_streak,
    'streak_bonus',      v_streak_bonus,
    'spin_type',         p_spin_type,
    'spin_cost',         v_spin_cost,
    'spin_cost_asset',   v_spin_asset,
    'jackpot_amount',    (SELECT jackpot_current_amount FROM public.wheel_config WHERE id = 1)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM,
    'error_code', 'INTERNAL_ERROR'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_add_collateral(p_loan_id uuid, p_additional_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id       uuid := auth.uid();
  v_loan          loans%ROWTYPE;
  v_user_balance  numeric;
  v_price_collateral numeric;
  v_price_borrow      numeric;
  v_new_ltv           numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_additional_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_loan FROM loans WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  SELECT available_balance INTO v_user_balance
  FROM user_balances WHERE user_id = v_user_id AND asset_symbol = v_loan.collateral_asset FOR UPDATE;

  IF NOT FOUND OR v_user_balance < p_additional_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant pour ajouter ce collateral');
  END IF;

  UPDATE user_balances SET available_balance = available_balance - p_additional_amount, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = v_loan.collateral_asset;

  UPDATE loans SET collateral_amount = collateral_amount + p_additional_amount
  WHERE id = p_loan_id;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'loan_collateral_lock', v_loan.collateral_asset, p_additional_amount, p_additional_amount, 'completed', now(),
          jsonb_build_object('loan_id', p_loan_id, 'reason', 'top_up'));

  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = v_loan.collateral_asset;
  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = v_loan.borrow_asset;

  v_new_ltv := ((v_loan.principal_amount + v_loan.accrued_interest) * v_price_borrow)
             / ((v_loan.collateral_amount + p_additional_amount) * v_price_collateral) * 100;

  RETURN jsonb_build_object(
    'success', true, 'loan_id', p_loan_id,
    'collateral_total', v_loan.collateral_amount + p_additional_amount,
    'new_ltv_pct', ROUND(v_new_ltv, 2)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_admin_reclaim_user_balance(p_user_id uuid, p_asset_symbol text, p_reason text, p_admin_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_available      numeric;
  v_staking        numeric;
  v_total          numeric;
  v_balance_before numeric;
  v_balance_after  numeric;
  v_stake          RECORD;
BEGIN
  SELECT available_balance, staking_balance INTO v_available, v_staking
  FROM public.user_balances
  WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun solde pour cet utilisateur/asset');
  END IF;

  v_total := v_available + v_staking;
  IF v_total <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde deja nul');
  END IF;

  FOR v_stake IN
    SELECT id, pool_id, amount FROM public.user_stakes
    WHERE user_id = p_user_id AND status = 'active'
      AND pool_id IN (SELECT id FROM public.staking_pools WHERE asset_symbol = p_asset_symbol)
    FOR UPDATE
  LOOP
    UPDATE public.user_stakes
    SET amount = 0, status = 'unstaked', pending_rewards = 0, updated_at = now()
    WHERE id = v_stake.id;

    UPDATE public.staking_pools
    SET total_staked = GREATEST(0, total_staked - v_stake.amount), updated_at = now()
    WHERE id = v_stake.pool_id;
  END LOOP;

  UPDATE public.user_balances
  SET available_balance = 0,
      staking_balance   = 0,
      updated_at        = now()
  WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol;

  INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected)
  VALUES (p_asset_symbol, v_total, v_total)
  ON CONFLICT (asset_symbol) DO UPDATE SET
    balance = treasury_wallets.balance + v_total,
    total_collected = treasury_wallets.total_collected + v_total,
    updated_at = now()
  RETURNING balance, balance - v_total INTO v_balance_after, v_balance_before;

  INSERT INTO public.treasury_ledger (
    asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason
  ) VALUES (
    p_asset_symbol, 'admin_reclaim', v_total, v_balance_before, v_balance_after, p_admin_id, p_reason
  );

  INSERT INTO public.transactions (
    user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata
  ) VALUES (
    p_user_id, 'admin_reclaim', p_asset_symbol, v_total, v_total, 'completed', now(),
    jsonb_build_object('reason', p_reason, 'available_reclaimed', v_available, 'staking_reclaimed', v_staking)
  );

  RETURN jsonb_build_object(
    'success', true,
    'user_id', p_user_id,
    'asset_symbol', p_asset_symbol,
    'available_reclaimed', v_available,
    'staking_reclaimed', v_staking,
    'total_reclaimed', v_total,
    'treasury_balance_after', v_balance_after
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_admin_score_credit_status(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_capacity jsonb;
  v_state    user_score_credit_state%ROWTYPE;
  v_active_loan score_loans%ROWTYPE;
BEGIN
  v_capacity := fn_score_credit_capacity(p_user_id);
  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = p_user_id;
  SELECT * INTO v_active_loan FROM score_loans WHERE user_id = p_user_id AND status = 'active';

  RETURN jsonb_build_object(
    'capacity', v_capacity,
    'conversion_rate_pct', COALESCE(v_state.conversion_rate_pct, 90),
    'default_count', COALESCE(v_state.default_count, 0),
    'last_default_at', v_state.last_default_at,
    'has_completed_first_loan', COALESCE(v_state.has_completed_first_loan, false),
    'active_loan', CASE WHEN v_active_loan.id IS NOT NULL THEN row_to_json(v_active_loan) ELSE NULL END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_admin_set_wheel_currency(p_asset text, p_spin_cost numeric, p_reset_jackpot boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old RECORD;
BEGIN
  IF p_spin_cost <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cout du spin invalide');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM supported_assets WHERE symbol = p_asset AND is_active = true) THEN
    RETURN jsonb_build_object('success', false, 'error', p_asset || ' n''est pas un actif actif/valide');
  END IF;

  SELECT paid_spin_cost_amount, paid_spin_cost_asset, jackpot_current_amount INTO v_old
  FROM wheel_config WHERE id = 1;

  UPDATE wheel_config
  SET paid_spin_cost_amount = p_spin_cost,
      paid_spin_cost_asset  = p_asset,
      jackpot_asset_symbol  = p_asset,
      jackpot_current_amount = CASE WHEN p_reset_jackpot THEN 0 ELSE jackpot_current_amount END,
      updated_at = now()
  WHERE id = 1;

  RETURN jsonb_build_object(
    'success', true,
    'previous_asset', v_old.paid_spin_cost_asset,
    'previous_cost', v_old.paid_spin_cost_amount,
    'previous_jackpot_wiped', CASE WHEN p_reset_jackpot THEN v_old.jackpot_current_amount ELSE 0 END,
    'new_asset', p_asset,
    'new_cost', p_spin_cost
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_award_engagement_points(p_user_id uuid, p_action_type text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cfg score_action_config%ROWTYPE;
  v_points numeric;
BEGIN
  SELECT * INTO v_cfg FROM score_action_config WHERE action_type = p_action_type AND is_active = true;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_points := v_cfg.points_min + floor(random() * (v_cfg.points_max - v_cfg.points_min + 1));

  INSERT INTO user_engagement_points (user_id, total_points, updated_at)
  VALUES (p_user_id, v_points, now())
  ON CONFLICT (user_id) DO UPDATE
  SET total_points = user_engagement_points.total_points + v_points, updated_at = now();
EXCEPTION WHEN OTHERS THEN
  -- Ne jamais casser l'action qui a declenche l'attribution de points
  NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_burn_tokens(p_asset_symbol text, p_amount numeric, p_reason text DEFAULT NULL::text, p_admin_id uuid DEFAULT NULL::uuid, p_tx_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_balance_before numeric;
  v_balance_after  numeric;
  v_burn_id        uuid;
BEGIN
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT balance INTO v_balance_before
  FROM public.treasury_wallets
  WHERE asset_symbol = p_asset_symbol
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucune tresorerie pour cet asset');
  END IF;

  IF v_balance_before < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde tresorerie insuffisant pour ce burn',
                               'balance_disponible', v_balance_before);
  END IF;

  UPDATE public.treasury_wallets
  SET balance = balance - p_amount,
      total_burned = total_burned + p_amount,
      updated_at = now()
  WHERE asset_symbol = p_asset_symbol
  RETURNING balance INTO v_balance_after;

  INSERT INTO public.treasury_ledger (
    asset_symbol, entry_type, amount, balance_before, balance_after,
    performed_by, reason
  ) VALUES (
    p_asset_symbol, 'burn', p_amount, v_balance_before, v_balance_after,
    p_admin_id, p_reason
  );

  INSERT INTO public.token_burns (
    asset_symbol, amount, reason, burned_by, tx_hash, status, source
  ) VALUES (
    p_asset_symbol, p_amount, p_reason, p_admin_id, p_tx_hash, 'completed', 'treasury'
  ) RETURNING id INTO v_burn_id;

  UPDATE public.supported_assets_metrics
  SET total_burned = total_burned + p_amount, last_updated = now()
  WHERE asset_symbol = p_asset_symbol;

  RETURN jsonb_build_object(
    'success', true,
    'burn_id', v_burn_id,
    'asset_symbol', p_asset_symbol,
    'amount_burned', p_amount,
    'treasury_balance_after', v_balance_after
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_check_and_liquidate_loans()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_loan RECORD;
  v_liquidated_count int := 0;
BEGIN
  FOR v_loan IN SELECT id FROM loans WHERE status = 'active' LOOP
    IF (fn_liquidate_loan(v_loan.id)->>'success')::boolean THEN
      v_liquidated_count := v_liquidated_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'loans_liquidated', v_liquidated_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_check_score_loan_defaults()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config score_credit_config%ROWTYPE;
  v_loan   RECORD;
  v_interest numeric;
  v_count  int := 0;
BEGIN
  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;

  FOR v_loan IN SELECT * FROM score_loans WHERE status = 'active' AND grace_until < now() FOR UPDATE LOOP
    v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100
                  * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);

    UPDATE score_loans
    SET status = 'defaulted', accrued_interest = v_interest, closed_at = now()
    WHERE id = v_loan.id;

    INSERT INTO user_score_credit_state (user_id, conversion_rate_pct, default_count, last_default_at, updated_at)
    VALUES (v_loan.user_id, v_config.conversion_rate_base_pct, 1, now(), now())
    ON CONFLICT (user_id) DO UPDATE
    SET conversion_rate_pct = v_config.conversion_rate_base_pct,
        default_count = user_score_credit_state.default_count + 1,
        last_default_at = now(),
        updated_at = now();

    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
    VALUES (v_loan.user_id, 'score_loan_defaulted', v_loan.asset_symbol, v_loan.principal_amount + v_interest,
            v_loan.principal_amount + v_interest, 'completed', now(), jsonb_build_object('loan_id', v_loan.id));

    INSERT INTO notifications (user_id, type, title, message, data)
    VALUES (v_loan.user_id, 'score_loan_defaulted', 'Pret en retard',
            'Ton pret n''a pas ete rembourse a temps. Tes prochains credits serviront en priorite a le solder.',
            jsonb_build_object('loan_id', v_loan.id));

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('processed', v_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_compute_wakati_daily_price()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_state          public.wakati_reserve_state%ROWTYPE;
  v_period_start   timestamptz := date_trunc('day', now()) - interval '1 day';
  v_period_end     timestamptz := date_trunc('day', now());
  v_revenue_usd    numeric;
  v_payouts_usd    numeric;
  v_net_profit_usd numeric;
  v_contribution   numeric;
  v_reserve_new    numeric;
  v_circulating    numeric;
  v_price_old      numeric;
  v_raw_price      numeric;
  v_min_allowed    numeric;
  v_max_allowed    numeric;
  v_capped_price   numeric;
  v_final_price    numeric;
  v_was_capped     boolean := false;
BEGIN
  SELECT * INTO v_state FROM public.wakati_reserve_state WHERE id = 1 FOR UPDATE;
  IF NOT FOUND OR NOT v_state.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'Systeme de prix WAKATI inactif ou non configure');
  END IF;

  SELECT COALESCE(SUM(pf.amount * ap.price_usd), 0) INTO v_revenue_usd
  FROM public.platform_fees pf
  JOIN public.asset_prices ap ON ap.asset_symbol = pf.asset_symbol
  WHERE pf.is_test = false
    AND pf.fee_type != 'game_net_loss'
    AND pf.collected_at >= v_period_start
    AND pf.collected_at < v_period_end;

  SELECT COALESCE(SUM(t.amount * ap.price_usd), 0) INTO v_payouts_usd
  FROM public.transactions t
  JOIN public.asset_prices ap ON ap.asset_symbol = t.asset_symbol
  WHERE t.type IN ('game_win', 'referral_bonus', 'staking_reward')
    AND t.status = 'completed'
    AND t.created_at >= v_period_start
    AND t.created_at < v_period_end;

  v_net_profit_usd := v_revenue_usd - v_payouts_usd;

  -- ✅ Un mauvais jour retire désormais vraiment de la réserve (même taux
  -- que la contribution positive), au lieu de simplement ne rien ajouter.
  -- La réserve elle-même ne descend jamais sous 0.
  v_contribution := v_net_profit_usd * v_state.profit_share_pct / 100;
  v_reserve_new  := GREATEST(v_state.reserve_usd + v_contribution, 0);

  -- Offre en circulation = détenue par les utilisateurs (exclut la trésorerie
  -- non distribuée). Si le staking dilue (mint sans contrepartie), ce nombre
  -- grossit et fait mécaniquement baisser raw_price ci-dessous.
  SELECT COALESCE(SUM(available_balance), 0) INTO v_circulating
  FROM public.user_balances WHERE asset_symbol = 'WAKATI';

  SELECT price_usd INTO v_price_old FROM public.asset_prices WHERE asset_symbol = 'WAKATI';

  IF v_circulating <= 0 THEN
    v_raw_price := v_price_old;
  ELSE
    v_raw_price := v_reserve_new / v_circulating;
  END IF;

  -- Plafond de variation quotidienne, dans les DEUX sens désormais utile.
  v_min_allowed  := v_price_old * (1 - v_state.max_daily_change_pct / 100);
  v_max_allowed  := v_price_old * (1 + v_state.max_daily_change_pct / 100);
  v_capped_price := LEAST(GREATEST(v_raw_price, v_min_allowed), v_max_allowed);
  v_was_capped   := (v_capped_price != v_raw_price);

  -- Mur ultime : jamais en dessous du plancher, quoi qu'il arrive.
  v_final_price := GREATEST(v_capped_price, v_state.price_floor_usd);

  UPDATE public.asset_prices SET price_usd = v_final_price, updated_at = now() WHERE asset_symbol = 'WAKATI';

  UPDATE public.wakati_reserve_state
  SET reserve_usd = v_reserve_new, last_computed_at = now(), updated_at = now()
  WHERE id = 1;

  INSERT INTO public.wakati_price_history (
    computed_for_date, net_profit_usd, reserve_contribution_usd, reserve_usd_after,
    circulating_supply, price_before_usd, raw_price_usd, final_price_usd, was_capped
  ) VALUES (
    v_period_start::date, v_net_profit_usd, v_contribution, v_reserve_new,
    v_circulating, v_price_old, v_raw_price, v_final_price, v_was_capped
  );

  RETURN jsonb_build_object(
    'success', true,
    'period', v_period_start::date,
    'net_profit_usd', v_net_profit_usd,
    'reserve_contribution_usd', v_contribution,
    'reserve_usd', v_reserve_new,
    'circulating_supply', v_circulating,
    'price_old', v_price_old,
    'price_new', v_final_price,
    'was_capped', v_was_capped
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_confirm_withdrawal_fee(p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx transactions%ROWTYPE;
  v_fee_id uuid;
BEGIN
  SELECT * INTO v_tx FROM transactions
  WHERE id = p_transaction_id AND type = 'withdrawal'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction introuvable');
  END IF;

  IF v_tx.fee IS NULL OR v_tx.fee <= 0 THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'Aucun frais a collecter');
  END IF;

  -- Idempotence : si un frais a deja ete collecte pour cette transaction, on sort.
  IF EXISTS (
    SELECT 1 FROM platform_fees
    WHERE source_transaction_id = p_transaction_id AND fee_type = 'withdraw_fee'
  ) THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'Frais deja collecte');
  END IF;

  v_fee_id := collect_fee_to_platform(v_tx.asset_symbol, v_tx.fee, 'withdraw_fee', v_tx.user_id, p_transaction_id);

  RETURN jsonb_build_object('success', v_fee_id IS NOT NULL, 'fee_id', v_fee_id, 'fee_collected', v_tx.fee);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_extend_score_loan(p_loan_id uuid, p_preview boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id      uuid := auth.uid();
  v_loan         score_loans%ROWTYPE;
  v_config       score_credit_config%ROWTYPE;
  v_interest     numeric;
  v_new_principal numeric;
  v_fee          numeric;
  v_balance      numeric;
  v_new_apr      numeric;
  v_new_due_at   timestamptz;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT * INTO v_loan FROM score_loans
  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active'
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;

  IF now() > v_loan.grace_until THEN
    RETURN jsonb_build_object('success', false, 'error', 'Delai de grace depasse, extension indisponible');
  END IF;

  IF v_loan.extensions_used >= v_config.max_extensions_per_loan THEN
    RETURN jsonb_build_object('success', false, 'error', 'Nombre maximum de prolongations atteint pour ce pret');
  END IF;

  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100
                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);
  v_new_principal := v_loan.principal_amount + v_interest;
  v_fee := ROUND(v_new_principal * v_config.extension_fee_pct / 100, 8);
  v_new_apr := v_loan.apr_rate_snapshot + v_config.extension_apr_surcharge_pct;
  v_new_due_at := now() + (v_config.extension_days || ' days')::interval;

  IF p_preview THEN
    RETURN jsonb_build_object(
      'success', true, 'preview', true, 'fee_charged', v_fee, 'fee_asset', v_loan.asset_symbol,
      'new_principal_owed', v_new_principal, 'current_apr_rate_pct', v_loan.apr_rate_snapshot,
      'new_apr_rate_pct', v_new_apr, 'new_due_at', v_new_due_at,
      'extensions_used', v_loan.extensions_used, 'extensions_remaining', v_config.max_extensions_per_loan - v_loan.extensions_used
    );
  END IF;

  SELECT available_balance INTO v_balance FROM user_balances
  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol FOR UPDATE;
  IF NOT FOUND OR v_balance < v_fee THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Solde insuffisant pour payer le frais de prolongation',
      'fee_required', v_fee, 'asset_symbol', v_loan.asset_symbol
    );
  END IF;

  UPDATE user_balances SET available_balance = available_balance - v_fee, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol;

  PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_fee, 'score_loan_extension_fee', v_user_id, NULL);

  UPDATE score_loans SET
    principal_amount = v_new_principal,
    accrued_interest = 0,
    apr_rate_snapshot = v_new_apr,
    opened_at = now(),
    due_at = v_new_due_at,
    grace_until = v_new_due_at + (v_config.grace_period_hours || ' hours')::interval,
    extensions_used = extensions_used + 1
  WHERE id = p_loan_id;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'score_loan_extended', v_loan.asset_symbol, v_fee, v_fee, 'completed', now(),
          jsonb_build_object('loan_id', p_loan_id, 'new_principal', v_new_principal, 'new_apr_rate_pct', v_new_apr, 'new_due_at', v_new_due_at));

  RETURN jsonb_build_object(
    'success', true, 'preview', false, 'fee_charged', v_fee, 'fee_asset', v_loan.asset_symbol,
    'new_principal_owed', v_new_principal, 'new_apr_rate_pct', v_new_apr, 'new_due_at', v_new_due_at,
    'extensions_used', v_loan.extensions_used + 1, 'extensions_remaining', v_config.max_extensions_per_loan - (v_loan.extensions_used + 1)
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_liquidate_loan(p_loan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_loan               loans%ROWTYPE;
  v_penalty_pct        numeric;
  v_price_collateral   numeric;
  v_price_borrow       numeric;
  v_debt               numeric;
  v_debt_usd           numeric;
  v_collateral_usd     numeric;
  v_ltv                numeric;
  v_collateral_needed  numeric;
  v_surplus            numeric;
  v_penalty            numeric;
  v_to_treasury        numeric;
  v_to_user            numeric;
  v_treasury_before    numeric;
BEGIN
  SELECT * INTO v_loan FROM loans WHERE id = p_loan_id AND status = 'active' FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  SELECT liquidation_penalty_pct INTO v_penalty_pct FROM lending_collateral_config WHERE asset_symbol = v_loan.collateral_asset;
  v_penalty_pct := COALESCE(v_penalty_pct, 0);

  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = v_loan.collateral_asset;
  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = v_loan.borrow_asset;

  IF v_price_collateral IS NULL OR v_price_borrow IS NULL OR v_price_collateral <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible, liquidation impossible');
  END IF;

  v_debt           := v_loan.principal_amount + v_loan.accrued_interest;
  v_debt_usd       := v_debt * v_price_borrow;
  v_collateral_usd := v_loan.collateral_amount * v_price_collateral;
  v_ltv            := (v_debt_usd / v_collateral_usd) * 100;

  IF v_ltv < v_loan.liquidation_ltv_snapshot THEN
    RETURN jsonb_build_object('success', false, 'error', 'LTV encore sain, pas de liquidation necessaire', 'ltv_actuel', ROUND(v_ltv,2));
  END IF;

  v_collateral_needed := LEAST(v_loan.collateral_amount, v_debt_usd / v_price_collateral);
  v_surplus           := v_loan.collateral_amount - v_collateral_needed;
  v_penalty           := ROUND(v_surplus * v_penalty_pct / 100, 8);
  v_to_user            := v_surplus - v_penalty;
  v_to_treasury         := v_collateral_needed + v_penalty;

  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.collateral_asset FOR UPDATE;

  INSERT INTO treasury_wallets (asset_symbol, balance, total_collected)
  VALUES (v_loan.collateral_asset, v_to_treasury, v_to_treasury)
  ON CONFLICT (asset_symbol) DO UPDATE
  SET balance = treasury_wallets.balance + v_to_treasury, total_collected = treasury_wallets.total_collected + v_to_treasury, updated_at = now();

  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, reason)
  VALUES (v_loan.collateral_asset, 'liquidation', v_to_treasury, COALESCE(v_treasury_before,0), COALESCE(v_treasury_before,0) + v_to_treasury,
          'Liquidation pret ' || p_loan_id::text || ' - LTV ' || ROUND(v_ltv,2)::text || '% (dont penalite ' || v_penalty::text || ')');

  IF v_to_user > 0 THEN
    UPDATE user_balances SET available_balance = available_balance + v_to_user, updated_at = now()
    WHERE user_id = v_loan.user_id AND asset_symbol = v_loan.collateral_asset;

    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
    VALUES (v_loan.user_id, 'loan_collateral_release', v_loan.collateral_asset, v_to_user, v_to_user, 'completed', now(),
            jsonb_build_object('loan_id', p_loan_id, 'reason', 'liquidation_surplus', 'penalty_deducted', v_penalty));
  END IF;

  INSERT INTO loan_liquidations (
    loan_id, collateral_to_treasury, collateral_to_user, debt_settled,
    collateral_price_usd, borrow_price_usd, ltv_at_liquidation
  ) VALUES (
    p_loan_id, v_to_treasury, v_to_user, v_debt, v_price_collateral, v_price_borrow, v_ltv
  );

  UPDATE loans SET status = 'liquidated', closed_at = now() WHERE id = p_loan_id;

  RETURN jsonb_build_object(
    'success', true, 'loan_id', p_loan_id, 'ltv_at_liquidation', ROUND(v_ltv,2),
    'collateral_to_treasury', v_to_treasury, 'penalty_amount', v_penalty,
    'collateral_returned_to_user', v_to_user
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_open_loan(p_collateral_asset text, p_collateral_amount numeric, p_borrow_asset text, p_borrow_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id            uuid := auth.uid();
  v_coll_cfg           lending_collateral_config%ROWTYPE;
  v_borrow_cfg         lending_borrow_config%ROWTYPE;
  v_existing_loan       loans%ROWTYPE;
  v_price_collateral   numeric;
  v_price_borrow       numeric;
  v_ltv_pct            numeric;
  v_combined_collateral numeric;
  v_combined_debt       numeric;
  v_collateral_needed  numeric;
  v_collateral_balance numeric;
  v_treasury_balance   numeric;
  v_current_exposure   numeric;
  v_loan_id            uuid;
  v_merged              boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_collateral_asset = p_borrow_asset THEN
    RETURN jsonb_build_object('success', false, 'error', 'Le collateral et l''emprunt doivent etre des actifs differents');
  END IF;

  IF p_collateral_amount <= 0 OR p_borrow_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montants invalides');
  END IF;

  SELECT * INTO v_coll_cfg FROM lending_collateral_config WHERE asset_symbol = p_collateral_asset AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', p_collateral_asset || ' n''est pas utilisable comme collateral');
  END IF;

  SELECT * INTO v_borrow_cfg FROM lending_borrow_config WHERE asset_symbol = p_borrow_asset AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', p_borrow_asset || ' n''est pas empruntable');
  END IF;

  IF p_borrow_amount < v_borrow_cfg.min_borrow_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant en dessous du minimum autorise', 'minimum', v_borrow_cfg.min_borrow_amount);
  END IF;

  IF v_borrow_cfg.max_borrow_amount IS NOT NULL AND p_borrow_amount > v_borrow_cfg.max_borrow_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant au dessus du maximum autorise', 'maximum', v_borrow_cfg.max_borrow_amount);
  END IF;

  IF v_borrow_cfg.max_total_borrowed IS NOT NULL THEN
    SELECT COALESCE(SUM(principal_amount), 0) INTO v_current_exposure
    FROM loans WHERE borrow_asset = p_borrow_asset AND status = 'active';

    IF v_current_exposure + p_borrow_amount > v_borrow_cfg.max_total_borrowed THEN
      RETURN jsonb_build_object('success', false, 'error', 'Plafond d''exposition atteint pour ' || p_borrow_asset,
                                 'exposition_actuelle', v_current_exposure, 'plafond', v_borrow_cfg.max_total_borrowed);
    END IF;
  END IF;

  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = p_collateral_asset;
  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = p_borrow_asset;

  IF v_price_collateral IS NULL OR v_price_borrow IS NULL OR v_price_collateral <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour cet actif');
  END IF;

  -- Chercher un pret actif existant avec exactement le meme couple collateral/emprunt
  SELECT * INTO v_existing_loan FROM loans
  WHERE user_id = v_user_id AND collateral_asset = p_collateral_asset
    AND borrow_asset = p_borrow_asset AND status = 'active'
  FOR UPDATE;

  IF FOUND THEN
    v_merged := true;
    v_combined_collateral := v_existing_loan.collateral_amount + p_collateral_amount;
    v_combined_debt := v_existing_loan.principal_amount + v_existing_loan.accrued_interest + p_borrow_amount;
    v_ltv_pct := (v_combined_debt * v_price_borrow) / (v_combined_collateral * v_price_collateral) * 100;
  ELSE
    v_ltv_pct := (p_borrow_amount * v_price_borrow) / (p_collateral_amount * v_price_collateral) * 100;
  END IF;

  IF v_ltv_pct > v_coll_cfg.max_ltv_pct THEN
    RETURN jsonb_build_object('success', false, 'error', 'LTV trop eleve pour ce collateral',
                               'ltv_demande', ROUND(v_ltv_pct,2), 'ltv_max', v_coll_cfg.max_ltv_pct);
  END IF;

  v_collateral_needed := p_collateral_amount + v_coll_cfg.fixed_fee_amount;

  SELECT available_balance INTO v_collateral_balance
  FROM user_balances WHERE user_id = v_user_id AND asset_symbol = p_collateral_asset FOR UPDATE;

  IF NOT FOUND OR v_collateral_balance < v_collateral_needed THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde collateral insuffisant (collateral + frais requis)');
  END IF;

  SELECT balance INTO v_treasury_balance FROM treasury_wallets WHERE asset_symbol = p_borrow_asset FOR UPDATE;
  IF NOT FOUND OR v_treasury_balance < p_borrow_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Liquidite insuffisante en tresorerie pour cet actif',
                               'demande', p_borrow_amount, 'disponible', COALESCE(v_treasury_balance,0));
  END IF;

  UPDATE user_balances SET available_balance = available_balance - v_collateral_needed, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = p_collateral_asset;

  INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)
  VALUES (v_user_id, p_borrow_asset, p_borrow_amount, now())
  ON CONFLICT (user_id, asset_symbol) DO UPDATE
  SET available_balance = user_balances.available_balance + p_borrow_amount, updated_at = now();

  UPDATE treasury_wallets
  SET balance = balance - p_borrow_amount, total_withdrawn = total_withdrawn + p_borrow_amount, updated_at = now()
  WHERE asset_symbol = p_borrow_asset;

  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
  VALUES (p_borrow_asset, 'loan_disbursement', p_borrow_amount, v_treasury_balance, v_treasury_balance - p_borrow_amount,
          v_user_id, CASE WHEN v_merged THEN 'Ajout a un pret existant' ELSE 'Ouverture pret' END);

  IF v_coll_cfg.fixed_fee_amount > 0 THEN
    PERFORM collect_fee_to_platform(p_collateral_asset, v_coll_cfg.fixed_fee_amount, 'loan_origination_fee', v_user_id, NULL);
  END IF;

  IF v_merged THEN
    -- Fusionner avec le pret actif existant plutot que d'en creer un second
    UPDATE loans SET
      collateral_amount  = collateral_amount + p_collateral_amount,
      principal_amount   = principal_amount + p_borrow_amount,
      fixed_fee_charged  = fixed_fee_charged + v_coll_cfg.fixed_fee_amount
    WHERE id = v_existing_loan.id;

    v_loan_id := v_existing_loan.id;
  ELSE
    INSERT INTO loans (
      user_id, collateral_asset, collateral_amount, borrow_asset, principal_amount,
      apr_rate_snapshot, liquidation_ltv_snapshot, fixed_fee_charged, fixed_fee_asset
    ) VALUES (
      v_user_id, p_collateral_asset, p_collateral_amount, p_borrow_asset, p_borrow_amount,
      v_borrow_cfg.apr_rate_pct, v_coll_cfg.liquidation_ltv_pct, v_coll_cfg.fixed_fee_amount, p_collateral_asset
    ) RETURNING id INTO v_loan_id;
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'loan_collateral_lock', p_collateral_asset, p_collateral_amount, p_collateral_amount, 'completed', now(),
          jsonb_build_object('loan_id', v_loan_id, 'merged', v_merged));

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'loan_borrowed', p_borrow_asset, p_borrow_amount, p_borrow_amount, 'completed', now(),
          jsonb_build_object('loan_id', v_loan_id, 'merged', v_merged));

  IF v_coll_cfg.fixed_fee_amount > 0 THEN
    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
    VALUES (v_user_id, 'fee', p_collateral_asset, v_coll_cfg.fixed_fee_amount, v_coll_cfg.fixed_fee_amount, 'completed', now(),
            jsonb_build_object('loan_id', v_loan_id, 'fee_type', 'loan_origination_fee'));
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'loan_id', v_loan_id, 'merged', v_merged, 'ltv_pct', ROUND(v_ltv_pct,2),
    'collateral_locked', p_collateral_amount, 'borrowed', p_borrow_amount,
    'fixed_fee_charged', v_coll_cfg.fixed_fee_amount, 'fixed_fee_asset', p_collateral_asset,
    'apr_rate_pct', v_borrow_cfg.apr_rate_pct
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_open_score_loan(p_user_id uuid, p_asset_symbol text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config       score_credit_config%ROWTYPE;
  v_asset_cfg    score_loan_asset_config%ROWTYPE;
  v_state        user_score_credit_state%ROWTYPE;
  v_capacity     jsonb;
  v_price        numeric;
  v_amount_usd   numeric;
  v_fee          numeric;
  v_net          numeric;
  v_treasury_before numeric;
  v_loan_id      uuid;
  v_due_at       timestamptz;
BEGIN
  IF auth.uid() IS DISTINCT FROM p_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;

  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;

  SELECT * INTO v_asset_cfg FROM score_loan_asset_config WHERE asset_symbol = p_asset_symbol AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', p_asset_symbol || ' non disponible pour ce type de pret');
  END IF;

  IF p_amount < v_asset_cfg.min_borrow_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant en dessous du minimum', 'minimum', v_asset_cfg.min_borrow_amount);
  END IF;

  -- Un seul pret actif PAR ACTIF (avant : un seul pret actif tout actif confondu).
  -- Pour ajouter au meme actif, utiliser fn_topup_score_loan.
  IF EXISTS (SELECT 1 FROM score_loans WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol AND status = 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Un pret ' || p_asset_symbol || ' est deja en cours, utilise "Ajouter" pour l''augmenter');
  END IF;

  v_capacity := fn_score_credit_capacity(p_user_id);
  IF NOT (v_capacity->>'eligible')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', v_capacity->>'reason');
  END IF;

  SELECT price_usd INTO v_price FROM asset_prices WHERE asset_symbol = p_asset_symbol;
  IF v_price IS NULL OR v_price <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour cet actif');
  END IF;

  v_amount_usd := p_amount * v_price;
  IF v_amount_usd > (v_capacity->>'available_usd')::numeric THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant superieur a ta capacite actuelle');
  END IF;

  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO user_score_credit_state (user_id, conversion_rate_pct)
    VALUES (p_user_id, v_config.conversion_rate_base_pct)
    RETURNING * INTO v_state;
  END IF;

  v_fee := ROUND(v_asset_cfg.fixed_fee_amount * (1 + v_state.default_count * (v_config.default_fee_multiplier - 1)), 8);
  v_net := p_amount - v_fee;

  IF v_net <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant trop faible pour couvrir le frais d''ouverture');
  END IF;

  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = p_asset_symbol FOR UPDATE;
  IF NOT FOUND OR v_treasury_before < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Liquidite insuffisante en tresorerie pour cet actif');
  END IF;

  UPDATE treasury_wallets SET balance = balance - p_amount, total_withdrawn = total_withdrawn + p_amount, updated_at = now()
  WHERE asset_symbol = p_asset_symbol;

  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
  VALUES (p_asset_symbol, 'loan_disbursement', p_amount, v_treasury_before, v_treasury_before - p_amount,
          p_user_id, 'Ouverture pret-score');

  INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)
  VALUES (p_user_id, p_asset_symbol, v_net, now())
  ON CONFLICT (user_id, asset_symbol) DO UPDATE
  SET available_balance = user_balances.available_balance + v_net, updated_at = now();

  PERFORM collect_fee_to_platform(p_asset_symbol, v_fee, 'score_loan_origination_fee', p_user_id, NULL);

  v_due_at := now() + (v_config.loan_duration_days || ' days')::interval;

  INSERT INTO score_loans (user_id, asset_symbol, principal_amount, apr_rate_snapshot, fixed_fee_charged, status, opened_at, due_at, grace_until)
  VALUES (p_user_id, p_asset_symbol, p_amount, v_asset_cfg.apr_rate_pct, v_fee, 'active', now(), v_due_at,
          v_due_at + (v_config.grace_period_hours || ' hours')::interval)
  RETURNING id INTO v_loan_id;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (p_user_id, 'score_loan_borrowed', p_asset_symbol, v_net, v_net, 'completed', now(), jsonb_build_object('loan_id', v_loan_id));

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (p_user_id, 'score_loan_fee', p_asset_symbol, v_fee, v_fee, 'completed', now(), jsonb_build_object('loan_id', v_loan_id));

  RETURN jsonb_build_object(
    'success', true, 'loan_id', v_loan_id, 'amount_received', v_net, 'fee_charged', v_fee,
    'total_owed', p_amount, 'apr_rate_pct', v_asset_cfg.apr_rate_pct, 'due_at', v_due_at
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_place_bet(p_direction text, p_amount numeric, p_price_at_bet numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id     uuid := auth.uid();
  v_cfg         prediction_config%ROWTYPE;
  v_balance     numeric;
  v_bet_amount  numeric;
  v_resolves_at timestamptz;
  v_bet_id      uuid;
  v_bets_today  int;
  v_last_bet_at timestamptz;
BEGIN
  -- Auth
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  -- Validation direction
  IF p_direction NOT IN ('UP','DOWN') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Direction invalide (UP ou DOWN)');
  END IF;

  -- Charger la config
  SELECT * INTO v_cfg FROM prediction_config WHERE id = 1;

  IF NOT v_cfg.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'Le jeu est temporairement désactivé');
  END IF;

  -- Montant de la mise selon le mode
  IF v_cfg.bet_mode = 'fixed' THEN
    v_bet_amount := v_cfg.bet_amount;
  ELSE
    v_bet_amount := p_amount;
    IF v_bet_amount < v_cfg.bet_min OR v_bet_amount > v_cfg.bet_max THEN
      RETURN jsonb_build_object('success', false, 'error',
        'Montant invalide (min ' || v_cfg.bet_min || ' / max ' || v_cfg.bet_max || ')');
    END IF;
  END IF;

  -- Limite de paris par jour
  SELECT COUNT(*) INTO v_bets_today
  FROM prediction_bets
  WHERE user_id = v_user_id
    AND bet_at >= CURRENT_DATE
    AND status != 'cancelled';

  IF v_bets_today >= v_cfg.max_bets_per_day THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Limite de ' || v_cfg.max_bets_per_day || ' paris par jour atteinte');
  END IF;

  -- Cooldown entre deux paris
  SELECT last_bet_at INTO v_last_bet_at
  FROM prediction_user_stats
  WHERE user_id = v_user_id;

  IF v_last_bet_at IS NOT NULL AND
     EXTRACT(EPOCH FROM (now() - v_last_bet_at)) < v_cfg.cooldown_seconds THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Attendez encore ' ||
      (v_cfg.cooldown_seconds - FLOOR(EXTRACT(EPOCH FROM (now() - v_last_bet_at))))::int ||
      ' secondes avant de rejouer');
  END IF;

  -- Vérifier le solde disponible (FOR UPDATE pour éviter double-dépense)
  SELECT available_balance INTO v_balance
  FROM user_balances
  WHERE user_id = v_user_id AND asset_symbol = v_cfg.currency_symbol
  FOR UPDATE;

  IF v_balance IS NULL OR v_balance < v_bet_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant');
  END IF;

  -- Calculer la date de résolution
  v_resolves_at := now() + (v_cfg.duration_seconds || ' seconds')::interval;

  -- Débiter le solde
  UPDATE user_balances
  SET available_balance = available_balance - v_bet_amount,
      updated_at        = now()
  WHERE user_id = v_user_id AND asset_symbol = v_cfg.currency_symbol;

  -- Créer le pari
  INSERT INTO prediction_bets (
    user_id, direction, bet_amount, currency_symbol,
    price_at_bet, resolves_at,
    win_multiplier, duration_seconds, asset_symbol
  ) VALUES (
    v_user_id, p_direction, v_bet_amount, v_cfg.currency_symbol,
    p_price_at_bet, v_resolves_at,
    v_cfg.win_multiplier, v_cfg.duration_seconds, v_cfg.asset_symbol
  )
  RETURNING id INTO v_bet_id;

  -- Enregistrer la transaction de mise
  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'game_bet', v_cfg.currency_symbol, v_bet_amount, v_bet_amount, 'completed', now(),
          jsonb_build_object('game', 'prediction', 'bet_id', v_bet_id, 'direction', p_direction));

  -- Initialiser ou mettre à jour les stats user
  INSERT INTO prediction_user_stats (user_id, total_bets, total_wagered, last_bet_at)
  VALUES (v_user_id, 1, v_bet_amount, now())
  ON CONFLICT (user_id) DO UPDATE SET
    total_bets   = prediction_user_stats.total_bets + 1,
    total_wagered = prediction_user_stats.total_wagered + v_bet_amount,
    last_bet_at  = now(),
    updated_at   = now();

  RETURN jsonb_build_object(
    'success',       true,
    'bet_id',        v_bet_id,
    'direction',     p_direction,
    'bet_amount',    v_bet_amount,
    'price_at_bet',  p_price_at_bet,
    'resolves_at',   v_resolves_at,
    'win_multiplier', v_cfg.win_multiplier,
    'potential_win', ROUND(v_bet_amount * v_cfg.win_multiplier, 4)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_remove_collateral(p_loan_id uuid, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id           uuid := auth.uid();
  v_loan               loans%ROWTYPE;
  v_coll_cfg           lending_collateral_config%ROWTYPE;
  v_price_collateral   numeric;
  v_price_borrow       numeric;
  v_new_collateral     numeric;
  v_new_ltv            numeric;
  v_debt               numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_loan FROM loans
  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  v_new_collateral := v_loan.collateral_amount - p_amount;

  IF v_new_collateral <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Impossible de retirer tout le collateral ainsi - rembourse le pret pour le liberer entierement');
  END IF;

  SELECT * INTO v_coll_cfg FROM lending_collateral_config WHERE asset_symbol = v_loan.collateral_asset;

  SELECT price_usd INTO v_price_collateral FROM asset_prices WHERE asset_symbol = v_loan.collateral_asset;
  SELECT price_usd INTO v_price_borrow     FROM asset_prices WHERE asset_symbol = v_loan.borrow_asset;

  IF v_price_collateral IS NULL OR v_price_borrow IS NULL OR v_price_collateral <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible, retrait impossible');
  END IF;

  v_debt    := v_loan.principal_amount + v_loan.accrued_interest;
  v_new_ltv := (v_debt * v_price_borrow) / (v_new_collateral * v_price_collateral) * 100;

  -- Le LTV apres retrait ne doit pas depasser le seuil MAX d'ouverture
  -- (meme logique de securite qu'a l'ouverture d'un nouveau pret)
  IF v_new_ltv > v_coll_cfg.max_ltv_pct THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Retrait refuse : le LTV resultant serait trop eleve',
      'ltv_apres_retrait', ROUND(v_new_ltv,2), 'ltv_max', v_coll_cfg.max_ltv_pct);
  END IF;

  UPDATE loans SET collateral_amount = v_new_collateral WHERE id = p_loan_id;

  UPDATE user_balances
  SET available_balance = available_balance + p_amount, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = v_loan.collateral_asset;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'loan_collateral_release', v_loan.collateral_asset, p_amount, p_amount, 'completed', now(),
          jsonb_build_object('loan_id', p_loan_id, 'reason', 'partial_withdrawal'));

  RETURN jsonb_build_object(
    'success', true, 'loan_id', p_loan_id,
    'collateral_removed', p_amount,
    'collateral_remaining', v_new_collateral,
    'new_ltv_pct', ROUND(v_new_ltv, 2)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_repay_loan(p_loan_id uuid, p_repay_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id         uuid := auth.uid();
  v_loan            loans%ROWTYPE;
  v_owed            numeric;
  v_repay           numeric;
  v_interest_paid   numeric;
  v_principal_paid  numeric;
  v_user_balance    numeric;
  v_treasury_before numeric;
  v_fully_repaid    boolean;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_repay_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_loan FROM loans
  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  v_owed := v_loan.principal_amount + v_loan.accrued_interest;
  v_repay := LEAST(p_repay_amount, v_owed);
  v_interest_paid := LEAST(v_repay, v_loan.accrued_interest);
  v_principal_paid := v_repay - v_interest_paid;

  SELECT available_balance INTO v_user_balance
  FROM user_balances WHERE user_id = v_user_id AND asset_symbol = v_loan.borrow_asset FOR UPDATE;

  IF NOT FOUND OR v_user_balance < v_repay THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant pour rembourser');
  END IF;

  UPDATE user_balances SET available_balance = available_balance - v_repay, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = v_loan.borrow_asset;

  -- Tolerance relative (0.01% du du, avec un plancher) au lieu d'un epsilon fixe :
  -- evite qu'un peu d'interet accru entre l'affichage cote client et l'execution
  -- laisse le pret bloque en "active" a cause d'une poussiere residuelle.
  v_fully_repaid := (v_owed - v_repay) <= GREATEST(v_owed * 0.0001, 0.00000001);

  UPDATE loans SET
    principal_amount = CASE WHEN v_fully_repaid THEN 0 ELSE principal_amount - v_principal_paid END,
    accrued_interest  = CASE WHEN v_fully_repaid THEN 0 ELSE accrued_interest - v_interest_paid END,
    status           = CASE WHEN v_fully_repaid THEN 'repaid' ELSE 'active' END,
    closed_at        = CASE WHEN v_fully_repaid THEN now() ELSE NULL END
  WHERE id = p_loan_id;

  IF v_principal_paid > 0 THEN
    SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.borrow_asset FOR UPDATE;
    UPDATE treasury_wallets SET balance = balance + v_principal_paid, updated_at = now()
    WHERE asset_symbol = v_loan.borrow_asset;
    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
    VALUES (v_loan.borrow_asset, 'loan_repayment', v_principal_paid, v_treasury_before, v_treasury_before + v_principal_paid,
            v_user_id, 'Remboursement principal pret ' || p_loan_id::text);
  END IF;

  IF v_interest_paid > 0 THEN
    PERFORM collect_fee_to_platform(v_loan.borrow_asset, v_interest_paid, 'loan_interest', v_user_id, NULL);
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'loan_repaid', v_loan.borrow_asset, v_repay, v_repay, 'completed', now(),
          jsonb_build_object('loan_id', p_loan_id, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid));

  IF v_fully_repaid THEN
    INSERT INTO user_balances (user_id, asset_symbol, available_balance, updated_at)
    VALUES (v_user_id, v_loan.collateral_asset, v_loan.collateral_amount, now())
    ON CONFLICT (user_id, asset_symbol) DO UPDATE
    SET available_balance = user_balances.available_balance + v_loan.collateral_amount, updated_at = now();

    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
    VALUES (v_user_id, 'loan_collateral_release', v_loan.collateral_asset, v_loan.collateral_amount, v_loan.collateral_amount, 'completed', now(),
            jsonb_build_object('loan_id', p_loan_id));
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'loan_id', p_loan_id, 'repaid', v_repay,
    'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,
    'fully_repaid', v_fully_repaid,
    'collateral_released', CASE WHEN v_fully_repaid THEN v_loan.collateral_amount ELSE 0 END
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_repay_score_loan(p_loan_id uuid, p_repay_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id        uuid := auth.uid();
  v_loan           score_loans%ROWTYPE;
  v_config         score_credit_config%ROWTYPE;
  v_interest       numeric;
  v_owed           numeric;
  v_repay          numeric;
  v_interest_paid  numeric;
  v_principal_paid numeric;
  v_balance        numeric;
  v_fully_repaid   boolean;
  v_treasury_before numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;
  IF p_repay_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_loan FROM score_loans
  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100
                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);
  v_owed := v_loan.principal_amount + v_interest;
  v_repay := LEAST(p_repay_amount, v_owed);
  v_interest_paid := LEAST(v_repay, v_interest);
  v_principal_paid := v_repay - v_interest_paid;

  SELECT available_balance INTO v_balance FROM user_balances
  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol FOR UPDATE;
  IF NOT FOUND OR v_balance < v_repay THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant pour rembourser');
  END IF;

  UPDATE user_balances SET available_balance = available_balance - v_repay, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol;

  v_fully_repaid := (v_owed - v_repay) <= GREATEST(v_owed * 0.0001, 0.00000001);

  UPDATE score_loans SET
    principal_amount = CASE WHEN v_fully_repaid THEN 0 ELSE principal_amount - v_principal_paid END,
    accrued_interest = CASE WHEN v_fully_repaid THEN 0 ELSE v_interest - v_interest_paid END,
    status = CASE WHEN v_fully_repaid THEN 'repaid' ELSE 'active' END,
    closed_at = CASE WHEN v_fully_repaid THEN now() ELSE NULL END
  WHERE id = p_loan_id;

  IF v_principal_paid > 0 THEN
    SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.asset_symbol FOR UPDATE;
    UPDATE treasury_wallets SET balance = balance + v_principal_paid, updated_at = now() WHERE asset_symbol = v_loan.asset_symbol;
    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
    VALUES (v_loan.asset_symbol, 'loan_repayment', v_principal_paid, v_treasury_before, v_treasury_before + v_principal_paid,
            v_user_id, 'Remboursement pret-score ' || p_loan_id::text);
  END IF;

  IF v_interest_paid > 0 THEN
    PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_interest_paid, 'score_loan_interest', v_user_id, NULL);
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'score_loan_repaid', v_loan.asset_symbol, v_repay, v_repay, 'completed', now(),
          jsonb_build_object('loan_id', p_loan_id, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid));

  IF v_fully_repaid THEN
    SELECT * INTO v_config FROM score_credit_config WHERE id = 1;
    UPDATE user_score_credit_state
    SET conversion_rate_pct = LEAST(conversion_rate_pct + v_config.conversion_rate_step_pct, v_config.conversion_rate_max_pct),
        has_completed_first_loan = true,
        updated_at = now()
    WHERE user_id = v_user_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'repaid', v_repay, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,
    'fully_repaid', v_fully_repaid, 'remaining', GREATEST(v_owed - v_repay, 0)
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_repay_score_loan_with_asset(p_loan_id uuid, p_source_asset text, p_repay_amount_in_loan_asset numeric, p_preview boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id        uuid := auth.uid();
  v_loan           score_loans%ROWTYPE;
  v_config         score_credit_config%ROWTYPE;
  v_interest       numeric;
  v_owed           numeric;
  v_repay          numeric;
  v_interest_paid  numeric;
  v_principal_paid numeric;
  v_loan_price     numeric;
  v_source_price   numeric;
  v_repay_usd      numeric;
  v_source_needed_base numeric;
  v_conversion_fee_source numeric;
  v_source_total   numeric;
  v_source_balance numeric;
  v_fully_repaid   boolean;
  v_treasury_before numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;
  IF p_repay_amount_in_loan_asset <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_loan FROM score_loans
  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  IF p_source_asset = v_loan.asset_symbol THEN
    RETURN jsonb_build_object('success', false, 'error', 'Utilise le remboursement standard pour ce meme actif');
  END IF;

  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;

  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100
                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);
  v_owed := v_loan.principal_amount + v_interest;
  v_repay := LEAST(p_repay_amount_in_loan_asset, v_owed);
  v_interest_paid := LEAST(v_repay, v_interest);
  v_principal_paid := v_repay - v_interest_paid;

  SELECT price_usd INTO v_loan_price FROM asset_prices WHERE asset_symbol = v_loan.asset_symbol;
  SELECT price_usd INTO v_source_price FROM asset_prices WHERE asset_symbol = p_source_asset;
  IF v_loan_price IS NULL OR v_loan_price <= 0 OR v_source_price IS NULL OR v_source_price <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour la conversion');
  END IF;

  v_repay_usd := v_repay * v_loan_price;
  v_source_needed_base := v_repay_usd / v_source_price;
  v_conversion_fee_source := ROUND(v_source_needed_base * v_config.cross_asset_repay_fee_pct / 100, 8);
  v_source_total := v_source_needed_base + v_conversion_fee_source;

  IF p_preview THEN
    SELECT available_balance INTO v_source_balance FROM user_balances
    WHERE user_id = v_user_id AND asset_symbol = p_source_asset;
    RETURN jsonb_build_object(
      'success', true, 'preview', true, 'repay_amount', v_repay, 'loan_asset', v_loan.asset_symbol,
      'source_asset', p_source_asset, 'source_amount_required', v_source_total,
      'conversion_fee_source', v_conversion_fee_source, 'source_balance_available', COALESCE(v_source_balance, 0),
      'sufficient_balance', COALESCE(v_source_balance, 0) >= v_source_total
    );
  END IF;

  SELECT available_balance INTO v_source_balance FROM user_balances
  WHERE user_id = v_user_id AND asset_symbol = p_source_asset FOR UPDATE;
  IF NOT FOUND OR v_source_balance < v_source_total THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Solde insuffisant dans cet actif pour couvrir le remboursement et le frais de conversion',
      'source_amount_required', v_source_total, 'source_asset', p_source_asset
    );
  END IF;

  UPDATE user_balances SET available_balance = available_balance - v_source_total, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = p_source_asset;

  IF v_conversion_fee_source > 0 THEN
    PERFORM collect_fee_to_platform(p_source_asset, v_conversion_fee_source, 'score_loan_cross_asset_fee', v_user_id, NULL);
  END IF;

  v_fully_repaid := (v_owed - v_repay) <= GREATEST(v_owed * 0.0001, 0.00000001);

  UPDATE score_loans SET
    principal_amount = CASE WHEN v_fully_repaid THEN 0 ELSE principal_amount - v_principal_paid END,
    accrued_interest = CASE WHEN v_fully_repaid THEN 0 ELSE v_interest - v_interest_paid END,
    status = CASE WHEN v_fully_repaid THEN 'repaid' ELSE 'active' END,
    closed_at = CASE WHEN v_fully_repaid THEN now() ELSE NULL END
  WHERE id = p_loan_id;

  IF v_principal_paid > 0 THEN
    SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.asset_symbol FOR UPDATE;
    UPDATE treasury_wallets SET balance = balance + v_principal_paid, updated_at = now() WHERE asset_symbol = v_loan.asset_symbol;
    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
    VALUES (v_loan.asset_symbol, 'loan_repayment', v_principal_paid, v_treasury_before, v_treasury_before + v_principal_paid,
            v_user_id, 'Remboursement pret-score (cross-asset) ' || p_loan_id::text);
  END IF;

  IF v_interest_paid > 0 THEN
    PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_interest_paid, 'score_loan_interest', v_user_id, NULL);
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'score_loan_repaid_cross_asset', v_loan.asset_symbol, v_repay, v_repay, 'completed', now(),
          jsonb_build_object(
            'loan_id', p_loan_id, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,
            'source_asset', p_source_asset, 'source_amount_debited', v_source_total, 'conversion_fee_source', v_conversion_fee_source
          ));

  IF v_fully_repaid THEN
    UPDATE user_score_credit_state
    SET conversion_rate_pct = LEAST(conversion_rate_pct + v_config.conversion_rate_step_pct, v_config.conversion_rate_max_pct),
        has_completed_first_loan = true,
        updated_at = now()
    WHERE user_id = v_user_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'preview', false, 'repaid', v_repay, 'principal_paid', v_principal_paid, 'interest_paid', v_interest_paid,
    'fully_repaid', v_fully_repaid, 'remaining', GREATEST(v_owed - v_repay, 0),
    'source_asset', p_source_asset, 'source_amount_debited', v_source_total, 'conversion_fee_source', v_conversion_fee_source
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_resolve_bet(p_bet_id uuid, p_price_at_resolution numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id     uuid := auth.uid();
  v_bet         prediction_bets%ROWTYPE;
  v_won         boolean;
  v_payout      numeric;
  v_profit      numeric;
  v_new_status  text;
  v_streak_win  int;
  v_streak_loss int;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT * INTO v_bet
  FROM prediction_bets
  WHERE id = p_bet_id AND user_id = v_user_id AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pari introuvable ou déjà résolu');
  END IF;

  IF now() < v_bet.resolves_at - interval '5 seconds' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Le timer n''est pas encore écoulé');
  END IF;

  IF p_price_at_resolution = v_bet.price_at_bet THEN
    v_new_status := 'cancelled';
    v_payout     := v_bet.bet_amount;
    v_profit     := 0;
  ELSIF v_bet.direction = 'UP' THEN
    v_won := p_price_at_resolution > v_bet.price_at_bet;
  ELSE
    v_won := p_price_at_resolution < v_bet.price_at_bet;
  END IF;

  IF v_new_status IS NULL THEN
    IF v_won THEN
      v_new_status := 'won';
      v_payout     := ROUND(v_bet.bet_amount * v_bet.win_multiplier, 4);
      v_profit     := ROUND(v_payout - v_bet.bet_amount, 4);
    ELSE
      v_new_status := 'lost';
      v_payout     := 0;
      v_profit     := -v_bet.bet_amount;
    END IF;
  END IF;

  UPDATE prediction_bets SET
    status              = v_new_status,
    price_at_resolution = p_price_at_resolution,
    payout_amount       = v_payout,
    profit_amount       = v_profit,
    resolved_at         = now()
  WHERE id = p_bet_id;

  IF v_payout > 0 THEN
    UPDATE user_balances
    SET available_balance = available_balance + v_payout,
        updated_at        = now()
    WHERE user_id = v_user_id AND asset_symbol = v_bet.currency_symbol;

    IF v_new_status = 'won' THEN
      -- Seul le PROFIT (au-dela de la mise rendue) est finance par la tresorerie
      IF v_profit > 0 THEN
        PERFORM fn_treasury_debit_for_payout(
          v_bet.currency_symbol, v_profit, v_user_id, 'Gain pari prediction ' || p_bet_id::text
        );
      END IF;

      INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
      VALUES (v_user_id, 'game_win', v_bet.currency_symbol, v_payout, v_payout, 'completed', now(),
              jsonb_build_object('game', 'prediction', 'bet_id', p_bet_id,
                                 'direction', v_bet.direction, 'profit', v_profit));
    END IF;
  END IF;

  IF v_new_status = 'lost' THEN
    PERFORM collect_fee_to_platform(
      v_bet.currency_symbol, v_bet.bet_amount, 'game_house_edge', v_user_id, NULL
    );
  END IF;

  SELECT win_streak, loss_streak INTO v_streak_win, v_streak_loss
  FROM prediction_user_stats WHERE user_id = v_user_id;

  UPDATE prediction_user_stats SET
    total_wins    = total_wins   + CASE WHEN v_won THEN 1 ELSE 0 END,
    total_losses  = total_losses + CASE WHEN v_won = false AND v_new_status = 'lost' THEN 1 ELSE 0 END,
    total_won     = total_won    + CASE WHEN v_won THEN v_payout ELSE 0 END,
    total_lost    = total_lost   + CASE WHEN v_won = false AND v_new_status = 'lost' THEN v_bet.bet_amount ELSE 0 END,
    net_profit    = net_profit   + v_profit,
    win_streak    = CASE WHEN v_won THEN win_streak + 1 ELSE 0 END,
    best_win_streak = GREATEST(best_win_streak, CASE WHEN v_won THEN win_streak + 1 ELSE win_streak END),
    loss_streak   = CASE WHEN v_won = false AND v_new_status = 'lost' THEN loss_streak + 1 ELSE 0 END,
    updated_at    = now()
  WHERE user_id = v_user_id;

  RETURN jsonb_build_object(
    'success',              true,
    'status',               v_new_status,
    'won',                  v_won,
    'direction',            v_bet.direction,
    'price_at_bet',         v_bet.price_at_bet,
    'price_at_resolution',  p_price_at_resolution,
    'bet_amount',           v_bet.bet_amount,
    'payout_amount',        v_payout,
    'profit_amount',        v_profit
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_score_credit_capacity(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config          score_credit_config%ROWTYPE;
  v_state           user_score_credit_state%ROWTYPE;
  v_account_age     int;
  v_organic_fees_usd numeric;
  v_outstanding_usd numeric;
  v_raw_cap_usd     numeric;
  v_available_usd   numeric;
  v_progress        jsonb;
BEGIN
  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;

  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = p_user_id;
  IF NOT FOUND THEN
    v_state.conversion_rate_pct := v_config.conversion_rate_base_pct;
    v_state.default_count := 0;
    v_state.has_completed_first_loan := false;
  END IF;

  SELECT COALESCE(EXTRACT(DAY FROM now() - created_at), 0)::int INTO v_account_age
  FROM public.users WHERE id = p_user_id;

  SELECT COALESCE(SUM(
    pf.amount * ap.price_usd *
    CASE WHEN pf.fee_type = 'game_net_loss'
         THEN v_config.game_house_edge_weight_pct / 100
         ELSE 1
    END
  ), 0) INTO v_organic_fees_usd
  FROM platform_fees pf
  JOIN asset_prices ap ON ap.asset_symbol = pf.asset_symbol
  WHERE pf.source_user_id = p_user_id
    AND pf.is_test = false
    AND pf.fee_type NOT IN ('score_loan_origination_fee', 'score_loan_interest', 'game_house_edge')
    AND pf.collected_at >= now() - (v_config.fee_window_days || ' days')::interval;

  SELECT COALESCE(SUM((sl.principal_amount + sl.accrued_interest) * ap.price_usd), 0) INTO v_outstanding_usd
  FROM score_loans sl
  JOIN asset_prices ap ON ap.asset_symbol = sl.asset_symbol
  WHERE sl.user_id = p_user_id AND sl.status = 'active';

  v_raw_cap_usd := v_organic_fees_usd * v_state.conversion_rate_pct / 100;
  v_available_usd := GREATEST(v_raw_cap_usd - v_outstanding_usd, 0);
  v_available_usd := LEAST(v_available_usd, v_config.max_absolute_cap_usd);

  IF NOT v_state.has_completed_first_loan THEN
    v_available_usd := LEAST(v_available_usd, v_config.first_loan_cap_usd);
  END IF;

  v_progress := jsonb_build_object(
    'account_age_days', v_account_age,
    'min_account_age_days', v_config.min_account_age_days,
    'organic_fees_usd', v_organic_fees_usd,
    'min_fees_required_usd', v_config.min_fees_required_usd
  );

  IF NOT v_config.is_active THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Systeme temporairement indisponible', 'available_usd', 0) || v_progress;
  END IF;

  IF v_account_age < v_config.min_account_age_days THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Compte trop recent', 'available_usd', 0) || v_progress;
  END IF;

  IF v_organic_fees_usd < v_config.min_fees_required_usd THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Activite insuffisante sur l''app', 'available_usd', 0) || v_progress;
  END IF;

  IF v_available_usd <= 0 THEN
    RETURN jsonb_build_object('eligible', false, 'reason', 'Capacite d''emprunt epuisee', 'available_usd', 0) || v_progress;
  END IF;

  RETURN jsonb_build_object(
    'eligible', true,
    'available_usd', v_available_usd,
    'outstanding_usd', v_outstanding_usd,
    'conversion_rate_pct', v_state.conversion_rate_pct,
    'default_count', v_state.default_count
  ) || v_progress;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_score_loan_debt_recovery_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_increase numeric;
  v_loan     RECORD;
  v_recovered numeric;
  v_treasury_before numeric;
  v_remaining numeric;
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  v_increase := NEW.available_balance - OLD.available_balance;
  IF v_increase <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_loan FROM score_loans
  WHERE user_id = NEW.user_id AND asset_symbol = NEW.asset_symbol AND status = 'defaulted'
    AND (principal_amount + accrued_interest) > 0
  ORDER BY opened_at ASC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  v_recovered := LEAST(v_increase, v_loan.principal_amount + v_loan.accrued_interest);

  UPDATE user_balances
  SET available_balance = available_balance - v_recovered
  WHERE user_id = NEW.user_id AND asset_symbol = NEW.asset_symbol;

  v_remaining := v_loan.principal_amount + v_loan.accrued_interest - v_recovered;

  UPDATE score_loans
  SET principal_amount = GREATEST(principal_amount - v_recovered, 0),
      accrued_interest = GREATEST(accrued_interest - GREATEST(v_recovered - v_loan.principal_amount, 0), 0),
      status = CASE WHEN v_remaining <= 0.00000001 THEN 'repaid' ELSE 'defaulted' END,
      closed_at = CASE WHEN v_remaining <= 0.00000001 THEN now() ELSE closed_at END
  WHERE id = v_loan.id;

  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = NEW.asset_symbol FOR UPDATE;
  IF FOUND THEN
    UPDATE treasury_wallets SET balance = balance + v_recovered, updated_at = now() WHERE asset_symbol = NEW.asset_symbol;
    INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
    VALUES (NEW.asset_symbol, 'loan_repayment', v_recovered, v_treasury_before, v_treasury_before + v_recovered,
            NEW.user_id, 'Recouvrement auto pret-score defaillant ' || v_loan.id::text);
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (NEW.user_id, 'score_loan_debt_recovered', NEW.asset_symbol, v_recovered, v_recovered, 'completed', now(),
          jsonb_build_object('loan_id', v_loan.id));

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_stake(p_amount numeric, p_pool_id uuid DEFAULT 'f6c208e1-f277-4720-b303-45c1b607bf1f'::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id   uuid := auth.uid();
  v_pool      staking_pools%ROWTYPE;
  v_balance   numeric;
  v_stake_id  uuid;
  v_unlock_at timestamptz;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_pool FROM staking_pools WHERE id = p_pool_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan de staking introuvable');
  END IF;
  IF NOT v_pool.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ce plan de staking est temporairement désactivé');
  END IF;
  IF p_amount < v_pool.min_stake THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant inférieur au minimum requis (' || v_pool.min_stake || ')');
  END IF;
  IF v_pool.max_stake IS NOT NULL AND p_amount > v_pool.max_stake THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant supérieur au maximum autorisé (' || v_pool.max_stake || ')');
  END IF;
  IF v_pool.max_pool_capacity IS NOT NULL AND v_pool.total_staked + p_amount > v_pool.max_pool_capacity THEN
    RETURN jsonb_build_object('success', false, 'error', 'Capacité du plan atteinte');
  END IF;

  SELECT available_balance INTO v_balance
  FROM user_balances
  WHERE user_id = v_user_id AND asset_symbol = v_pool.asset_symbol
  FOR UPDATE;

  IF v_balance IS NULL OR v_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant');
  END IF;

  UPDATE user_balances
  SET
    available_balance = available_balance - p_amount,
    staking_balance    = staking_balance + p_amount,
    updated_at         = now()
  WHERE user_id = v_user_id AND asset_symbol = v_pool.asset_symbol;

  IF v_pool.lock_period_days > 0 THEN
    v_unlock_at := now() + (v_pool.lock_period_days || ' days')::interval;
  ELSE
    v_unlock_at := NULL;
  END IF;

  INSERT INTO user_stakes (user_id, pool_id, amount, status, initial_apy, staked_at, last_reward_calculation, unlock_at)
  VALUES (v_user_id, p_pool_id, p_amount, 'active', v_pool.base_apy, now(), now(), v_unlock_at)
  ON CONFLICT (user_id, pool_id, status)
  DO UPDATE SET
    amount      = user_stakes.amount + EXCLUDED.amount,
    initial_apy = v_pool.base_apy,
    -- Un nouvel ajout sur un pool bloqué repousse le déblocage sur le total
    unlock_at   = EXCLUDED.unlock_at,
    updated_at  = now()
  RETURNING id INTO v_stake_id;

  UPDATE staking_pools
  SET total_staked = total_staked + p_amount, updated_at = now()
  WHERE id = p_pool_id;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'stake', v_pool.asset_symbol, p_amount, p_amount, 'completed', now(),
          jsonb_build_object('pool_id', p_pool_id, 'stake_id', v_stake_id, 'apr', v_pool.base_apy));

  RETURN jsonb_build_object(
    'success', true,
    'staked', p_amount,
    'apr', v_pool.base_apy,
    'pool_id', p_pool_id,
    'unlock_at', v_unlock_at,
    'message', 'Staking activé avec succès'
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_topup_score_loan(p_loan_id uuid, p_additional_amount numeric, p_preview boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id      uuid := auth.uid();
  v_loan         score_loans%ROWTYPE;
  v_config       score_credit_config%ROWTYPE;
  v_asset_cfg    score_loan_asset_config%ROWTYPE;
  v_state        user_score_credit_state%ROWTYPE;
  v_capacity     jsonb;
  v_price        numeric;
  v_amount_usd   numeric;
  v_interest     numeric;
  v_capitalized_principal numeric;
  v_fee          numeric;
  v_net          numeric;
  v_treasury_before numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;
  IF p_additional_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_loan FROM score_loans
  WHERE id = p_loan_id AND user_id = v_user_id AND status = 'active' FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pret introuvable ou deja cloture');
  END IF;

  IF now() > v_loan.grace_until THEN
    RETURN jsonb_build_object('success', false, 'error', 'Delai de grace depasse, impossible d''ajouter a ce pret');
  END IF;

  SELECT * INTO v_config FROM score_credit_config WHERE id = 1;

  SELECT * INTO v_asset_cfg FROM score_loan_asset_config WHERE asset_symbol = v_loan.asset_symbol AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', v_loan.asset_symbol || ' n''est plus disponible pour ce type de pret');
  END IF;

  v_capacity := fn_score_credit_capacity(v_user_id);
  IF NOT (v_capacity->>'eligible')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', v_capacity->>'reason');
  END IF;

  SELECT price_usd INTO v_price FROM asset_prices WHERE asset_symbol = v_loan.asset_symbol;
  IF v_price IS NULL OR v_price <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Prix indisponible pour cet actif');
  END IF;

  v_amount_usd := p_additional_amount * v_price;
  IF v_amount_usd > (v_capacity->>'available_usd')::numeric THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Montant superieur a ta capacite actuelle',
      'available_usd', (v_capacity->>'available_usd')::numeric
    );
  END IF;

  v_interest := ROUND(v_loan.principal_amount * v_loan.apr_rate_snapshot / 100
                * (EXTRACT(EPOCH FROM now() - v_loan.opened_at)) / (365 * 86400), 8);
  v_capitalized_principal := v_loan.principal_amount + v_interest;

  SELECT * INTO v_state FROM user_score_credit_state WHERE user_id = v_user_id FOR UPDATE;
  v_fee := ROUND(v_asset_cfg.fixed_fee_amount * (1 + v_state.default_count * (v_config.default_fee_multiplier - 1)), 8);
  v_net := p_additional_amount - v_fee;
  IF v_net <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant trop faible pour couvrir le frais');
  END IF;

  IF p_preview THEN
    RETURN jsonb_build_object(
      'success', true, 'preview', true, 'fee_charged', v_fee, 'amount_received', v_net,
      'new_principal_owed', v_capitalized_principal + p_additional_amount,
      'asset_symbol', v_loan.asset_symbol
    );
  END IF;

  SELECT balance INTO v_treasury_before FROM treasury_wallets WHERE asset_symbol = v_loan.asset_symbol FOR UPDATE;
  IF NOT FOUND OR v_treasury_before < p_additional_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Liquidite insuffisante en tresorerie pour cet actif');
  END IF;

  UPDATE treasury_wallets SET balance = balance - p_additional_amount, total_withdrawn = total_withdrawn + p_additional_amount, updated_at = now()
  WHERE asset_symbol = v_loan.asset_symbol;

  INSERT INTO treasury_ledger (asset_symbol, entry_type, amount, balance_before, balance_after, performed_by, reason)
  VALUES (v_loan.asset_symbol, 'loan_disbursement', p_additional_amount, v_treasury_before, v_treasury_before - p_additional_amount,
          v_user_id, 'Ajout au pret-score ' || p_loan_id::text);

  UPDATE user_balances SET available_balance = available_balance + v_net, updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = v_loan.asset_symbol;

  PERFORM collect_fee_to_platform(v_loan.asset_symbol, v_fee, 'score_loan_origination_fee', v_user_id, NULL);

  UPDATE score_loans SET
    principal_amount = v_capitalized_principal + p_additional_amount,
    accrued_interest = 0,
    opened_at = now()
  WHERE id = p_loan_id;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'score_loan_topup', v_loan.asset_symbol, v_net, v_net, 'completed', now(),
          jsonb_build_object('loan_id', p_loan_id, 'fee_charged', v_fee, 'new_principal', v_capitalized_principal + p_additional_amount));

  RETURN jsonb_build_object(
    'success', true, 'preview', false, 'fee_charged', v_fee, 'amount_received', v_net,
    'new_principal_owed', v_capitalized_principal + p_additional_amount, 'asset_symbol', v_loan.asset_symbol
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_treasury_debit_for_payout(p_asset_symbol text, p_amount numeric, p_user_id uuid, p_reason text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_balance_before numeric;
  v_debit          numeric;
  v_shortfall      numeric;
  v_balance_after  numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN 0;
  END IF;

  SELECT balance INTO v_balance_before
  FROM public.treasury_wallets
  WHERE asset_symbol = p_asset_symbol
  FOR UPDATE;

  IF NOT FOUND THEN
    v_balance_before := 0;
    INSERT INTO public.treasury_wallets (asset_symbol, balance, total_collected)
    VALUES (p_asset_symbol, 0, 0)
    ON CONFLICT (asset_symbol) DO NOTHING;
  END IF;

  v_debit     := LEAST(p_amount, v_balance_before);
  v_shortfall := p_amount - v_debit;

  IF v_debit > 0 THEN
    UPDATE public.treasury_wallets
    SET balance = balance - v_debit,
        total_withdrawn = total_withdrawn + v_debit,
        updated_at = now()
    WHERE asset_symbol = p_asset_symbol
    RETURNING balance INTO v_balance_after;

    INSERT INTO public.treasury_ledger (
      asset_symbol, entry_type, amount, balance_before, balance_after,
      performed_by, reason
    ) VALUES (
      p_asset_symbol, 'payout_debit', v_debit, v_balance_before, v_balance_after,
      p_user_id, p_reason
    );
  END IF;

  IF v_shortfall > 0 THEN
    -- Tracabilite : la tresorerie n'a pas suffi a couvrir tout le gain.
    -- Le joueur est quand meme paye (voir appelant), mais ceci doit alerter un admin.
    INSERT INTO public.treasury_ledger (
      asset_symbol, entry_type, amount, balance_before, balance_after,
      performed_by, reason
    ) VALUES (
      p_asset_symbol, 'adjustment', v_shortfall, 0, 0,
      p_user_id, 'SHORTFALL: gain non couvert par la tresorerie - ' || COALESCE(p_reason, '')
    );
    RAISE WARNING 'Tresorerie insuffisante pour % %: manque de % (raison: %)', p_amount, p_asset_symbol, v_shortfall, p_reason;
  END IF;

  RETURN v_debit;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_unstake(p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id     uuid := auth.uid();
  v_asset       text := 'WAKATI';
  v_pool_id     uuid := 'f6c208e1-f277-4720-b303-45c1b607bf1f';
  v_stake       user_stakes%ROWTYPE;
  v_rewards     numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_stake
  FROM user_stakes
  WHERE user_id = v_user_id AND pool_id = v_pool_id AND status = 'active'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun staking actif');
  END IF;

  IF p_amount > v_stake.amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant supérieur au stake');
  END IF;

  v_rewards := v_stake.pending_rewards;

  IF p_amount = v_stake.amount THEN
    UPDATE user_stakes SET
      amount           = 0,
      status           = 'unstaked',
      pending_rewards  = 0,
      rewards_earned   = rewards_earned + v_rewards,
      updated_at       = now()
    WHERE id = v_stake.id;
  ELSE
    UPDATE user_stakes SET
      amount           = amount - p_amount,
      pending_rewards  = 0,
      rewards_earned   = rewards_earned + v_rewards,
      last_reward_calculation = now(),
      updated_at       = now()
    WHERE id = v_stake.id;
  END IF;

  UPDATE user_balances SET
    available_balance  = available_balance + p_amount + v_rewards,
    staking_balance    = GREATEST(0, staking_balance - p_amount),
    total_earned_staking = total_earned_staking + v_rewards,
    updated_at         = now()
  WHERE user_id = v_user_id AND asset_symbol = v_asset;

  UPDATE staking_pools SET
    total_staked             = GREATEST(0, total_staked - p_amount),
    total_rewards_distributed = total_rewards_distributed + v_rewards,
    updated_at               = now()
  WHERE id = v_pool_id;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'unstake', v_asset, p_amount, p_amount, 'completed', now(),
          jsonb_build_object('pool_id', v_pool_id, 'rewards_claimed', v_rewards));

  IF v_rewards > 0 THEN
    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
    VALUES (v_user_id, 'staking_reward', v_asset, v_rewards, v_rewards, 'completed', now(),
            jsonb_build_object('pool_id', v_pool_id));

    -- La recompense est financee par la tresorerie, pas creee du neant
    PERFORM fn_treasury_debit_for_payout(v_asset, v_rewards, v_user_id, 'Recompense staking - unstake');
  END IF;

  RETURN jsonb_build_object(
    'success',  true,
    'unstaked', p_amount,
    'rewards_claimed', v_rewards,
    'total_received', p_amount + v_rewards,
    'message', 'Retrait effectué avec succès'
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_unstake(p_amount numeric, p_pool_id uuid DEFAULT 'f6c208e1-f277-4720-b303-45c1b607bf1f'::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id     uuid := auth.uid();
  v_pool        staking_pools%ROWTYPE;
  v_stake       user_stakes%ROWTYPE;
  v_rewards     numeric;
  v_penalty     numeric := 0;
  v_net_amount  numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT * INTO v_pool FROM staking_pools WHERE id = p_pool_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Plan de staking introuvable');
  END IF;

  SELECT * INTO v_stake
  FROM user_stakes
  WHERE user_id = v_user_id AND pool_id = p_pool_id AND status = 'active'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun staking actif sur ce plan');
  END IF;

  IF p_amount > v_stake.amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant supérieur au stake');
  END IF;

  -- Plan bloqué encore verrouillé : vérifier si le retrait anticipé est autorisé
  IF v_stake.unlock_at IS NOT NULL AND now() < v_stake.unlock_at THEN
    IF NOT v_pool.instant_unstake_enabled THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Ce staking est bloqué jusqu''au ' || to_char(v_stake.unlock_at, 'DD/MM/YYYY'),
        'unlock_at', v_stake.unlock_at
      );
    END IF;
    v_penalty := ROUND(p_amount * COALESCE(v_pool.instant_unstake_fee_percent, 0) / 100.0, 8);
  END IF;

  v_rewards := v_stake.pending_rewards;
  v_net_amount := p_amount - v_penalty;

  IF p_amount = v_stake.amount THEN
    UPDATE user_stakes SET
      amount           = 0,
      status           = 'unstaked',
      pending_rewards  = 0,
      rewards_earned   = rewards_earned + v_rewards,
      unlock_at        = NULL,
      updated_at       = now()
    WHERE id = v_stake.id;
  ELSE
    UPDATE user_stakes SET
      amount           = amount - p_amount,
      pending_rewards  = 0,
      rewards_earned   = rewards_earned + v_rewards,
      last_reward_calculation = now(),
      updated_at       = now()
    WHERE id = v_stake.id;
  END IF;

  UPDATE user_balances SET
    available_balance    = available_balance + v_net_amount + v_rewards,
    staking_balance       = GREATEST(0, staking_balance - p_amount),
    total_earned_staking  = total_earned_staking + v_rewards,
    updated_at            = now()
  WHERE user_id = v_user_id AND asset_symbol = v_pool.asset_symbol;

  UPDATE staking_pools SET
    total_staked              = GREATEST(0, total_staked - p_amount),
    total_rewards_distributed = total_rewards_distributed + v_rewards,
    updated_at                = now()
  WHERE id = p_pool_id;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
  VALUES (v_user_id, 'unstake', v_pool.asset_symbol, p_amount, v_net_amount, 'completed', now(),
          jsonb_build_object('pool_id', p_pool_id, 'rewards_claimed', v_rewards, 'early_withdrawal_penalty', v_penalty));

  IF v_rewards > 0 THEN
    INSERT INTO transactions (user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata)
    VALUES (v_user_id, 'staking_reward', v_pool.asset_symbol, v_rewards, v_rewards, 'completed', now(),
            jsonb_build_object('pool_id', p_pool_id));

    PERFORM fn_treasury_debit_for_payout(v_pool.asset_symbol, v_rewards, v_user_id, 'Recompense staking - unstake');
  END IF;

  RETURN jsonb_build_object(
    'success',  true,
    'unstaked', p_amount,
    'penalty', v_penalty,
    'rewards_claimed', v_rewards,
    'total_received', v_net_amount + v_rewards,
    'message', CASE WHEN v_penalty > 0
      THEN 'Retrait anticipé effectué avec ' || v_penalty || ' ' || v_pool.asset_symbol || ' de frais'
      ELSE 'Retrait effectué avec succès' END
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_user_burn_tokens(p_asset_symbol text, p_amount numeric, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id         uuid := auth.uid();
  v_balance         numeric;
  v_new_balance     numeric;
  v_burn_id         uuid;
  v_total_burned    numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant invalide');
  END IF;

  SELECT available_balance INTO v_balance
  FROM public.user_balances
  WHERE user_id = v_user_id AND asset_symbol = p_asset_symbol
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun solde pour cet asset');
  END IF;

  IF v_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant', 'solde_disponible', v_balance);
  END IF;

  UPDATE public.user_balances
  SET available_balance = available_balance - p_amount,
      updated_at = now()
  WHERE user_id = v_user_id AND asset_symbol = p_asset_symbol
  RETURNING available_balance INTO v_new_balance;

  INSERT INTO public.token_burns (
    asset_symbol, amount, reason, burned_by, status, source
  ) VALUES (
    p_asset_symbol, p_amount, p_reason, v_user_id, 'completed', 'user'
  ) RETURNING id INTO v_burn_id;

  UPDATE public.supported_assets_metrics
  SET total_burned = total_burned + p_amount, last_updated = now()
  WHERE asset_symbol = p_asset_symbol
  RETURNING total_burned INTO v_total_burned;

  INSERT INTO public.transactions (
    user_id, type, asset_symbol, amount, net_amount, status, completed_at, metadata
  ) VALUES (
    v_user_id, 'burn', p_asset_symbol, p_amount, p_amount, 'completed', now(),
    jsonb_build_object('reason', p_reason, 'burn_id', v_burn_id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'burn_id', v_burn_id,
    'amount_burned', p_amount,
    'new_balance', v_new_balance,
    'asset_total_burned', v_total_burned
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_user_can_get_free_spins(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_created_at   timestamptz;
  v_fcfa_balance numeric;
BEGIN
  SELECT created_at INTO v_created_at FROM public.users WHERE id = p_user_id;

  IF v_created_at IS NULL THEN
    RETURN false;
  END IF;

  -- Nouvel utilisateur (moins de 15 jours) : toujours éligible.
  IF v_created_at >= NOW() - INTERVAL '15 days' THEN
    RETURN true;
  END IF;

  -- Ancien utilisateur : éligible seulement si solde FCFA actuel >= 500.
  SELECT available_balance INTO v_fcfa_balance
  FROM public.user_balances
  WHERE user_id = p_user_id AND asset_symbol = 'FCFA';

  RETURN COALESCE(v_fcfa_balance, 0) >= 500;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_wheel_state(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config    RECORD;
  v_stats     RECORD;
  v_now       TIMESTAMPTZ := NOW();
  v_eligible  BOOLEAN;
  v_daily     INTEGER;
BEGIN
  SELECT * INTO v_config FROM public.wheel_config WHERE id = 1;

  IF NOT v_config.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'Roue temporairement désactivée');
  END IF;

  v_eligible := public.fn_user_can_get_free_spins(p_user_id);
  v_daily    := CASE WHEN v_eligible THEN v_config.free_spins_daily ELSE 0 END;

  INSERT INTO public.user_wheel_stats (user_id, free_spins_remaining, free_spins_reset_at)
  VALUES (p_user_id, v_daily, date_trunc('day', v_now) + INTERVAL '1 day')
  ON CONFLICT (user_id) DO NOTHING;

  SELECT * INTO v_stats FROM public.user_wheel_stats WHERE user_id = p_user_id;

  IF v_stats.free_spins_reset_at <= v_now THEN
    UPDATE public.user_wheel_stats
    SET free_spins_remaining = v_daily,
        free_spins_reset_at  = date_trunc('day', v_now) + INTERVAL '1 day',
        updated_at           = v_now
    WHERE user_id = p_user_id;

    v_stats.free_spins_remaining := v_daily;
    v_stats.free_spins_reset_at  := date_trunc('day', v_now) + INTERVAL '1 day';
  END IF;

  RETURN jsonb_build_object(
    'success',              true,
    'free_spins_daily',     v_daily,
    'free_spins_eligible',  v_eligible,
    'paid_spin_cost',       v_config.paid_spin_cost_amount,
    'paid_spin_cost_asset', v_config.paid_spin_cost_asset,
    'jackpot_amount',       v_config.jackpot_current_amount,
    'jackpot_asset',        v_config.jackpot_asset_symbol,
    'free_spins_remaining', v_stats.free_spins_remaining,
    'free_spins_reset_at',  v_stats.free_spins_reset_at,
    'current_streak',       v_stats.current_streak,
    'longest_streak',       v_stats.longest_streak,
    'total_spins',          v_stats.total_spins,
    -- ✅ Messages configurables en BDD, éditables sans mise à jour de l'app.
    'messages',             COALESCE(v_config.messages, '{}'::jsonb),
    'wakati_balance',       COALESCE((
      SELECT available_balance FROM public.user_balances
      WHERE user_id = p_user_id AND asset_symbol = v_config.paid_spin_cost_asset
    ), 0)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referral_code text;
  v_username      text;
BEGIN
  -- Générer un code referral unique format WKT
  LOOP
    v_referral_code := 'WKT' || UPPER(SUBSTRING(MD5(RANDOM()::text || CLOCK_TIMESTAMP()::text) FROM 1 FOR 6));
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.users WHERE referral_code = v_referral_code
    );
  END LOOP;

  -- Username temporaire basé sur le nom Google ou l'email, tronqué à 20 chars
  v_username := COALESCE(
    LOWER(REGEXP_REPLACE(NEW.raw_user_meta_data->>'full_name', '[^a-zA-Z0-9_]', '', 'g')),
    LOWER(SPLIT_PART(NEW.email, '@', 1))
  );
  v_username := REGEXP_REPLACE(v_username, '[^a-zA-Z0-9_]', '', 'g');

  -- Tronquer à 20 chars max
  IF LENGTH(v_username) > 20 THEN
    v_username := SUBSTRING(v_username FROM 1 FOR 20);
  END IF;

  IF LENGTH(v_username) = 0 THEN
    v_username := 'user' || SUBSTRING(MD5(NEW.id::text) FROM 1 FOR 8);
  END IF;

  -- Dédoublonner si nécessaire
  IF EXISTS (SELECT 1 FROM public.users WHERE username = v_username) THEN
    v_username := SUBSTRING(v_username FROM 1 FOR 16) || SUBSTRING(MD5(RANDOM()::text) FROM 1 FOR 4);
  END IF;

  -- Insérer le profil
  INSERT INTO public.users (
    id,
    email,
    username,
    referral_code,
    referred_by,
    email_confirmed,
    profile_completed,
    is_verified,
    avatar_url
  ) VALUES (
    NEW.id,
    NEW.email,
    v_username,
    v_referral_code,
    NULL,
    COALESCE(NEW.email_confirmed_at IS NOT NULL, true),
    false,
    false,
    NEW.raw_user_meta_data->>'avatar_url'
  )
  ON CONFLICT (id) DO NOTHING;

  -- Initialiser balances, multiplicateurs, limites de transaction
  PERFORM public.initialize_user_data(NEW.id);

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'handle_new_auth_user error for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_user_auth_flow(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_user_profile jsonb;
  v_auth_user auth.users%ROWTYPE;
  v_is_new boolean := false;
  v_username text;
  v_referral_code text;
  v_retry_count integer := 0;
  v_max_retries constant integer := 3;
BEGIN
  -- 🔐 VÉRIFICATION DE SÉCURITÉ
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'User ID required',
      'code', 'INVALID_INPUT'
    );
  END IF;
  
  -- 1. RÉCUPÉRER L'UTILISATEUR AUTH
  SELECT * INTO v_auth_user
  FROM auth.users
  WHERE id = p_user_id AND deleted_at IS NULL;
  
  IF v_auth_user IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'User not found or deleted',
      'code', 'USER_NOT_FOUND'
    );
  END IF;
  
  -- 2. VÉRIFIER SI LE PROFIL EXISTE DÉJÀ
  SELECT to_jsonb(u.*) INTO v_user_profile
  FROM users u
  WHERE u.id = p_user_id;
  
  -- 3. PROFIL EXISTANT - RETOUR DIRECT
  IF v_user_profile IS NOT NULL THEN
    -- Mettre à jour email_confirmed si nécessaire
    IF v_auth_user.email_confirmed_at IS NOT NULL AND 
       (v_user_profile->>'email_confirmed')::boolean = false THEN
      UPDATE users 
      SET email_confirmed = true, updated_at = NOW()
      WHERE id = p_user_id;
      
      SELECT to_jsonb(u.*) INTO v_user_profile
      FROM users u WHERE u.id = p_user_id;
    END IF;
    
    RETURN jsonb_build_object(
      'success', true,
      'data', v_user_profile,
      'is_new', false,
      'message', 'Existing profile retrieved',
      'code', 'PROFILE_EXISTS'
    );
  END IF;
  
  -- 4. CRÉER LE PROFIL (CAS RARE - normalement fait par le trigger)
  v_is_new := true;
  
  -- Tentative de création avec retry en cas de conflit
  WHILE v_retry_count < v_max_retries LOOP
    BEGIN
      -- Générer username unique
      v_username := LOWER(SPLIT_PART(v_auth_user.email, '@', 1));
      v_username := REGEXP_REPLACE(v_username, '[^a-zA-Z0-9]', '', 'g');
      
      IF LENGTH(v_username) = 0 THEN
        v_username := 'user' || SUBSTRING(MD5(p_user_id::text) FROM 1 FOR 8);
      END IF;
      
      -- Ajouter suffixe si nécessaire
      IF v_retry_count > 0 THEN
        v_username := v_username || v_retry_count;
      END IF;
      
      -- Vérifier unicité username
      IF EXISTS (SELECT 1 FROM users WHERE username = v_username) THEN
        v_retry_count := v_retry_count + 1;
        CONTINUE;
      END IF;
      
      -- Générer code de parrainage
      v_referral_code := 'WKT' || UPPER(SUBSTRING(
        MD5(p_user_id::text || v_auth_user.email || EXTRACT(EPOCH FROM NOW())::text || v_retry_count::text) 
        FROM 1 FOR 7
      ));
      
      -- Vérifier unicité referral_code
      IF EXISTS (SELECT 1 FROM users WHERE referral_code = v_referral_code) THEN
        v_retry_count := v_retry_count + 1;
        CONTINUE;
      END IF;
      
      -- Insérer l'utilisateur
      INSERT INTO users (
        id,
        username,
        email,
        email_confirmed,
        referral_code,
        profile_completed,
        created_at,
        updated_at
      ) VALUES (
        p_user_id,
        v_username,
        v_auth_user.email,
        v_auth_user.email_confirmed_at IS NOT NULL,
        v_referral_code,
        false,
        v_auth_user.created_at,
        v_auth_user.created_at
      );
      
      -- Initialiser les données utilisateur (appel direct pour ce cas)
      PERFORM public.initialize_user_data(p_user_id);
      
      EXIT; -- Succès, sortir de la boucle
      
    EXCEPTION
      WHEN unique_violation THEN
        v_retry_count := v_retry_count + 1;
        IF v_retry_count >= v_max_retries THEN
          RAISE EXCEPTION 'Failed to create unique profile after % attempts', v_max_retries;
        END IF;
        -- Continuer la boucle
      WHEN OTHERS THEN
        -- Journaliser et propager
        INSERT INTO auth_logs (
          user_id,
          action,
          details,
          error_message,
          created_at
        ) VALUES (
          p_user_id,
          'profile_creation_manual_error',
          jsonb_build_object('email', v_auth_user.email, 'retry_count', v_retry_count),
          SQLERRM,
          NOW()
        );
        RAISE;
    END;
  END LOOP;
  
  -- 5. RÉCUPÉRER LE NOUVEAU PROFIL
  SELECT to_jsonb(u.*) INTO v_user_profile
  FROM users u
  WHERE u.id = p_user_id;
  
  -- 6. JOURNALISATION SUCCÈS
  INSERT INTO auth_logs (
    user_id,
    action,
    details,
    created_at
  ) VALUES (
    p_user_id,
    'profile_created_manual',
    jsonb_build_object(
      'is_new', true, 
      'username', v_username,
      'retries', v_retry_count
    ),
    NOW()
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'data', v_user_profile,
    'is_new', true,
    'message', 'New profile created successfully',
    'code', 'PROFILE_CREATED'
  );
  
EXCEPTION
  WHEN OTHERS THEN
    -- Retourner un profil minimal en cas d'erreur critique
    INSERT INTO auth_logs (
      user_id,
      action,
      details,
      error_message,
      created_at
    ) VALUES (
      p_user_id,
      'profile_creation_fallback',
      jsonb_build_object('email', COALESCE(v_auth_user.email, 'unknown')),
      SQLERRM,
      NOW()
    );
    
    -- Profil minimal pour éviter de bloquer l'application
    RETURN jsonb_build_object(
      'success', true,
      'data', jsonb_build_object(
        'id', p_user_id,
        'email', COALESCE(v_auth_user.email, ''),
        'username', COALESCE(v_username, 'user' || SUBSTRING(MD5(p_user_id::text) FROM 1 FOR 8)),
        'profile_completed', false,
        'created_at', NOW(),
        'is_fallback', true
      ),
      'is_new', true,
      'message', 'Profile created with fallback mode',
      'warning', 'Partial initialization: ' || SQLERRM,
      'code', 'PROFILE_FALLBACK'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.initiate_airtime_purchase(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_balance_check boolean;
  v_limit_check record;
  v_tx_id uuid;
BEGIN
  -- 1. Vérifier le solde
  SELECT check_balance(p_user_id, 'FCFA', p_amount) INTO v_balance_check;
  IF NOT v_balance_check THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde FCFA insuffisant');
  END IF;

  -- 2. Vérifier les limites
  SELECT * INTO v_limit_check FROM check_transaction_limit(p_user_id, p_amount, 'withdraw');
  IF NOT v_limit_check.allowed THEN
    RETURN jsonb_build_object('success', false, 'error', v_limit_check.message);
  END IF;

  -- 3. Débiter le solde
  PERFORM decrement_balance(p_user_id, 'FCFA', p_amount);

  -- 4. Créer la transaction pending
  INSERT INTO transactions (
    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata
  ) VALUES (
    p_user_id, 'airtime_purchase', 'FCFA', p_amount, 0, p_amount, 'pending',
    jsonb_build_object(
      'external_reference', p_external_reference,
      'phone', p_phone,
      'provider', 'campay',
      'operation_type', 'airtime'
    )
  ) RETURNING id INTO v_tx_id;

  -- 5. Mettre à jour les limites
  UPDATE user_transaction_limits 
  SET daily_withdraw_used = daily_withdraw_used + p_amount,
      monthly_withdraw_used = monthly_withdraw_used + p_amount,
      updated_at = now()
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object(
    'success', true, 
    'transaction_id', v_tx_id, 
    'external_reference', p_external_reference
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.initiate_campay_deposit(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text, p_environment text DEFAULT 'sandbox'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_min_deposit numeric;
  v_max_deposit numeric;
  v_cfg campay_config%ROWTYPE;
BEGIN
  SELECT * INTO v_cfg FROM campay_config WHERE id = 1;

  IF p_environment = 'production' THEN
    v_min_deposit := v_cfg.production_min_deposit;
    v_max_deposit := v_cfg.production_max_deposit;
  ELSE
    v_min_deposit := v_cfg.sandbox_min_deposit;
    v_max_deposit := v_cfg.sandbox_max_deposit;
  END IF;

  IF v_min_deposit IS NOT NULL AND p_amount < v_min_deposit THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant minimum de dépôt : ' || v_min_deposit || ' FCFA',
      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit
    );
  END IF;

  IF v_max_deposit IS NOT NULL AND p_amount > v_max_deposit THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant maximum de dépôt : ' || v_max_deposit || ' FCFA',
      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit
    );
  END IF;

  INSERT INTO transactions (
    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata
  ) VALUES (
    p_user_id, 'deposit', 'FCFA', p_amount, 0, p_amount, 'pending',
    jsonb_build_object(
      'external_reference', p_external_reference,
      'phone', p_phone,
      'provider', 'campay'
    )
  ) RETURNING id INTO v_tx_id;

  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_tx_id,
    'external_reference', p_external_reference,
    'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.initiate_campay_deposit(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_min_deposit numeric;
  v_max_deposit numeric;
BEGIN
  SELECT active_min_deposit, active_max_deposit INTO v_min_deposit, v_max_deposit
  FROM v_active_campay_limits;

  IF v_min_deposit IS NOT NULL AND p_amount < v_min_deposit THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant minimum de dépôt : ' || v_min_deposit || ' FCFA',
      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit
    );
  END IF;

  IF v_max_deposit IS NOT NULL AND p_amount > v_max_deposit THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant maximum de dépôt : ' || v_max_deposit || ' FCFA',
      'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit
    );
  END IF;

  INSERT INTO transactions (
    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata
  ) VALUES (
    p_user_id, 'deposit', 'FCFA', p_amount, 0, p_amount, 'pending',
    jsonb_build_object(
      'external_reference', p_external_reference,
      'phone', p_phone,
      'provider', 'campay'
    )
  ) RETURNING id INTO v_tx_id;

  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_tx_id,
    'external_reference', p_external_reference,
    'min_deposit', v_min_deposit, 'max_deposit', v_max_deposit
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.initiate_campay_withdrawal(p_user_id uuid, p_amount numeric, p_phone text, p_external_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_balance_check boolean;
  v_limit_check record;
  v_tx_id uuid;
  v_fee numeric;
  v_net_amount numeric;
  v_min_withdraw numeric;
BEGIN
  SELECT min_withdraw INTO v_min_withdraw FROM supported_assets WHERE symbol = 'FCFA';
  IF p_amount < v_min_withdraw THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant minimum de retrait : ' || v_min_withdraw || ' FCFA');
  END IF;

  SELECT check_balance(p_user_id, 'FCFA', p_amount) INTO v_balance_check;
  IF NOT v_balance_check THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde FCFA insuffisant');
  END IF;

  SELECT * INTO v_limit_check FROM check_transaction_limit(p_user_id, p_amount, 'withdraw');
  IF NOT v_limit_check.allowed THEN
    RETURN jsonb_build_object('success', false, 'error', v_limit_check.message);
  END IF;

  SELECT fee_amount, net_amount INTO v_fee, v_net_amount
  FROM calculate_fee('FCFA', p_amount, 'withdraw');

  IF v_net_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant insuffisant pour couvrir le frais de retrait');
  END IF;

  PERFORM decrement_balance(p_user_id, 'FCFA', p_amount);

  INSERT INTO transactions (
    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata
  ) VALUES (
    p_user_id, 'withdrawal', 'FCFA', p_amount, v_fee, v_net_amount, 'pending',
    jsonb_build_object(
      'external_reference', p_external_reference,
      'phone', p_phone,
      'provider', 'campay'
    )
  ) RETURNING id INTO v_tx_id;

  UPDATE user_transaction_limits
  SET daily_withdraw_used = daily_withdraw_used + p_amount,
      monthly_withdraw_used = monthly_withdraw_used + p_amount,
      updated_at = now()
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_tx_id,
    'external_reference', p_external_reference,
    'fee', v_fee,
    'net_amount', v_net_amount
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.initiate_mobile_money_deposit(p_user_id uuid, p_amount numeric, p_phone text, p_iso_code text, p_external_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_country payment_countries%ROWTYPE;
  v_msg text;
BEGIN
  SELECT pc.* INTO v_country
  FROM payment_countries pc
  JOIN payment_providers pp ON pp.code = pc.provider_code
  WHERE pc.iso_code = p_iso_code AND pc.is_active = true AND pp.is_active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pays non disponible pour le depot');
  END IF;

  IF NOT v_country.deposit_enabled THEN
    SELECT message_fr INTO v_msg FROM payment_error_messages WHERE failure_code = 'DEPOSIT_DISABLED';
    RETURN jsonb_build_object(
      'success', false,
      'error', COALESCE(v_msg, 'Les dépôts sont momentanément suspendus pour ce pays.'),
      'failure_code', 'DEPOSIT_DISABLED'
    );
  END IF;

  IF v_country.wallet_asset_symbol IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Configuration incomplete pour ce pays (actif de portefeuille manquant)');
  END IF;

  IF v_country.min_deposit IS NOT NULL AND p_amount < v_country.min_deposit THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant minimum de dépôt : ' || v_country.min_deposit || ' ' || v_country.currency_code,
      'min_deposit', v_country.min_deposit, 'max_deposit', v_country.max_deposit
    );
  END IF;

  IF v_country.max_deposit IS NOT NULL AND p_amount > v_country.max_deposit THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant maximum de dépôt : ' || v_country.max_deposit || ' ' || v_country.currency_code,
      'min_deposit', v_country.min_deposit, 'max_deposit', v_country.max_deposit
    );
  END IF;

  INSERT INTO transactions (
    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata
  ) VALUES (
    p_user_id, 'deposit', v_country.wallet_asset_symbol, p_amount, 0, p_amount, 'pending',
    jsonb_build_object(
      'external_reference', p_external_reference,
      'phone', p_phone,
      'provider', v_country.provider_code,
      'country_iso', p_iso_code,
      'display_currency', v_country.currency_code
    )
  ) RETURNING id INTO v_tx_id;

  RETURN jsonb_build_object(
    'success', true,
    'transaction_id', v_tx_id,
    'external_reference', p_external_reference,
    'provider', v_country.provider_code,
    'currency', v_country.currency_code,
    'wallet_asset', v_country.wallet_asset_symbol,
    'min_deposit', v_country.min_deposit, 'max_deposit', v_country.max_deposit
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.initiate_mobile_money_withdrawal(p_user_id uuid, p_amount numeric, p_phone text, p_iso_code text, p_external_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_country payment_countries%ROWTYPE;
  v_fee numeric;
  v_net numeric;
  v_balance numeric;
  v_tx_id uuid;
  v_msg text;
BEGIN
  SELECT pc.* INTO v_country
  FROM payment_countries pc
  JOIN payment_providers pp ON pp.code = pc.provider_code
  WHERE pc.iso_code = p_iso_code AND pc.is_active = true AND pp.is_active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Pays non disponible pour le retrait');
  END IF;

  IF NOT v_country.withdraw_enabled THEN
    SELECT message_fr INTO v_msg FROM payment_error_messages WHERE failure_code = 'WITHDRAW_DISABLED';
    RETURN jsonb_build_object(
      'success', false,
      'error', COALESCE(v_msg, 'Les retraits sont momentanément suspendus pour ce pays.'),
      'failure_code', 'WITHDRAW_DISABLED'
    );
  END IF;

  IF v_country.wallet_asset_symbol IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Configuration incomplete pour ce pays');
  END IF;

  IF v_country.min_withdraw IS NOT NULL AND p_amount < v_country.min_withdraw THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant minimum de retrait : ' || v_country.min_withdraw || ' ' || v_country.currency_code,
      'min_withdraw', v_country.min_withdraw, 'max_withdraw', v_country.max_withdraw
    );
  END IF;

  IF v_country.max_withdraw IS NOT NULL AND p_amount > v_country.max_withdraw THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Montant maximum de retrait : ' || v_country.max_withdraw || ' ' || v_country.currency_code,
      'min_withdraw', v_country.min_withdraw, 'max_withdraw', v_country.max_withdraw
    );
  END IF;

  -- [FIX 2026-09-19] Frais en pourcentage si configure (withdraw_fee_percentage),
  -- sinon on garde l'ancien comportement (montant fixe withdraw_fee) pour ne rien
  -- casser sur les pays/actifs pas encore bascules en %.
  IF v_country.withdraw_fee_percentage IS NOT NULL THEN
    v_fee := ROUND(p_amount * v_country.withdraw_fee_percentage / 100, 0);
  ELSE
    v_fee := COALESCE(v_country.withdraw_fee, 0);
  END IF;

  v_net := p_amount - v_fee;

  IF v_net <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Montant insuffisant pour couvrir les frais de retrait');
  END IF;

  SELECT available_balance INTO v_balance
  FROM user_balances
  WHERE user_id = p_user_id AND asset_symbol = v_country.wallet_asset_symbol
  FOR UPDATE;

  IF v_balance IS NULL OR v_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Solde insuffisant', 'available_balance', COALESCE(v_balance, 0));
  END IF;

  UPDATE user_balances
  SET available_balance = available_balance - p_amount, updated_at = now()
  WHERE user_id = p_user_id AND asset_symbol = v_country.wallet_asset_symbol;

  INSERT INTO transactions (user_id, type, asset_symbol, amount, fee, net_amount, status, metadata)
  VALUES (
    p_user_id, 'withdrawal', v_country.wallet_asset_symbol, p_amount, v_fee, v_net, 'pending',
    jsonb_build_object(
      'external_reference', p_external_reference, 'phone', p_phone, 'provider', v_country.provider_code,
      'country_iso', p_iso_code, 'display_currency', v_country.currency_code,
      'wallet_asset', v_country.wallet_asset_symbol, 'amount', p_amount
    )
  ) RETURNING id INTO v_tx_id;

  IF v_fee > 0 THEN
    PERFORM collect_fee_to_platform(v_country.wallet_asset_symbol, v_fee, 'withdraw_fee', p_user_id, v_tx_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'transaction_id', v_tx_id, 'provider', v_country.provider_code,
    'currency', v_country.currency_code, 'wallet_asset', v_country.wallet_asset_symbol,
    'fee', v_fee, 'net_amount', v_net
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_user_deposit(p_user_id uuid, p_asset_symbol text, p_network text, p_amount numeric, p_tx_hash text, p_onchain_address text)
 RETURNS TABLE(success boolean, message text, transaction_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_transaction_id uuid;
  v_asset_exists   boolean;
BEGIN
  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RETURN QUERY SELECT false, 'Accès non autorisé : les dépôts sont traités uniquement par le système', NULL::uuid;
    RETURN;
  END IF;

  IF p_amount <= 0 THEN
    RETURN QUERY SELECT false, 'Montant invalide', NULL::uuid;
    RETURN;
  END IF;

  IF p_tx_hash IS NULL OR trim(p_tx_hash) = '' THEN
    RETURN QUERY SELECT false, 'tx_hash manquant', NULL::uuid;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM transactions
    WHERE tx_hash = p_tx_hash AND type = 'deposit' AND status = 'completed'
  ) THEN
    RETURN QUERY SELECT false, 'Ce dépôt a déjà été traité (tx_hash en double)', NULL::uuid;
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM supported_assets WHERE symbol = p_asset_symbol AND network = p_network AND is_active = true
  ) INTO v_asset_exists;

  IF NOT v_asset_exists THEN
    RETURN QUERY SELECT false, 'Asset non supporté sur ce réseau', NULL::uuid;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM supported_assets WHERE symbol = p_asset_symbol AND network = p_network AND can_be_deposited = false
  ) THEN
    RETURN QUERY SELECT false, 'Dépôts suspendus pour cet actif', NULL::uuid;
    RETURN;
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, network, amount, status, tx_hash, metadata)
  VALUES (p_user_id, 'deposit', p_asset_symbol, p_network, p_amount, 'completed', p_tx_hash, jsonb_build_object('onchain_address', p_onchain_address))
  RETURNING id INTO v_transaction_id;

  INSERT INTO user_balances (user_id, asset_symbol, available_balance)
  VALUES (p_user_id, p_asset_symbol, p_amount)
  ON CONFLICT (user_id, asset_symbol) DO UPDATE SET
    available_balance = user_balances.available_balance + p_amount,
    total_deposited = COALESCE(user_balances.total_deposited, 0) + p_amount,
    updated_at = NOW();

  INSERT INTO notifications (user_id, type, title, message, data)
  VALUES (p_user_id, 'deposit_confirmed', 'Dépôt confirmé',
    format('Votre dépôt de %s %s a été confirmé', p_amount, p_asset_symbol),
    jsonb_build_object('transaction_id', v_transaction_id, 'amount', p_amount, 'asset', p_asset_symbol, 'tx_hash', p_tx_hash));

  PERFORM fn_award_engagement_points(p_user_id, 'deposit');

  RETURN QUERY SELECT true, 'Deposit processed successfully', v_transaction_id;
EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT false, 'Erreur: ' || SQLERRM, NULL::uuid;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_user_deposit_atomic(p_address_id uuid, p_user_id uuid, p_asset_symbol text, p_network text, p_current_balance numeric, p_onchain_address text)
 RETURNS TABLE(success boolean, message text, transaction_id uuid, deposit_amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_previous_balance numeric;
  v_deposit_amount numeric;
  v_transaction_id uuid;
  v_ledger_symbol text;
  v_tx_hash text;
BEGIN
  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    RETURN QUERY SELECT false, 'Accès non autorisé', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  SELECT cached_balance INTO v_previous_balance
  FROM user_addresses
  WHERE id = p_address_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Adresse introuvable', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  v_deposit_amount := p_current_balance - COALESCE(v_previous_balance, 0);

  -- Dépôts suspendus pour cet actif : on ne crédite pas et on NE met PAS à jour cached_balance,
  -- pour que le dépôt soit détecté et crédité normalement à la réactivation.
  IF v_deposit_amount > 0.000001 AND EXISTS (
    SELECT 1 FROM supported_assets
    WHERE symbol = p_asset_symbol AND network = p_network AND can_be_deposited = false
  ) THEN
    RETURN QUERY SELECT false, 'Dépôts suspendus pour cet actif', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  UPDATE user_addresses
  SET cached_balance = p_current_balance, last_balance_check = NOW()
  WHERE id = p_address_id;

  IF v_deposit_amount <= 0.000001 THEN
    RETURN QUERY SELECT true, 'Rien à créditer', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  SELECT ledger_symbol INTO v_ledger_symbol
  FROM supported_assets
  WHERE symbol = p_asset_symbol AND network = p_network AND is_active = true;

  IF v_ledger_symbol IS NULL THEN
    RETURN QUERY SELECT false, 'Asset non supporté', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  v_tx_hash := 'scan_' || p_address_id || '_' || COALESCE(v_previous_balance,0) || '_' || p_current_balance;

  IF EXISTS (SELECT 1 FROM transactions WHERE tx_hash = v_tx_hash AND type = 'deposit') THEN
    RETURN QUERY SELECT false, 'Doublon détecté et bloqué', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  INSERT INTO transactions (user_id, type, asset_symbol, network, amount, status, tx_hash, metadata)
  VALUES (p_user_id, 'deposit', v_ledger_symbol, p_network, v_deposit_amount, 'completed', v_tx_hash,
          jsonb_build_object('onchain_address', p_onchain_address, 'detection_method', 'balance_delta_atomic', 'source_symbol', p_asset_symbol))
  RETURNING id INTO v_transaction_id;

  INSERT INTO user_balances (user_id, asset_symbol, available_balance)
  VALUES (p_user_id, v_ledger_symbol, v_deposit_amount)
  ON CONFLICT (user_id, asset_symbol) DO UPDATE SET
    available_balance = user_balances.available_balance + v_deposit_amount,
    total_deposited = COALESCE(user_balances.total_deposited, 0) + v_deposit_amount,
    updated_at = NOW();

  INSERT INTO notifications (user_id, type, title, message, data)
  VALUES (p_user_id, 'deposit_confirmed', 'Dépôt confirmé',
    format('Votre dépôt de %s %s a été confirmé', v_deposit_amount, v_ledger_symbol),
    jsonb_build_object('transaction_id', v_transaction_id, 'amount', v_deposit_amount, 'asset', v_ledger_symbol));

  PERFORM fn_award_engagement_points(p_user_id, 'deposit');

  RETURN QUERY SELECT true, 'Deposit processed successfully', v_transaction_id, v_deposit_amount;
EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT false, 'Erreur: ' || SQLERRM, NULL::uuid, 0::numeric;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_all_metrics()
 RETURNS TABLE(asset text, calc_status text, message text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_asset          RECORD;
    v_total_credits  numeric;
    v_total_debits   numeric;
    v_user_balances  numeric;
    v_net_position   numeric;
BEGIN
    FOR v_asset IN SELECT symbol FROM supported_assets WHERE is_active = true
    LOOP
        BEGIN
            SELECT COALESCE(SUM(
                CASE WHEN get_transaction_impact(t.type) = 'credit' THEN t.amount ELSE 0 END
            ), 0) INTO v_total_credits
            FROM transactions t
            WHERE t.asset_symbol = v_asset.symbol AND t.status = 'completed';

            SELECT COALESCE(SUM(
                CASE WHEN get_transaction_impact(t.type) = 'debit' THEN t.amount ELSE 0 END
            ), 0) INTO v_total_debits
            FROM transactions t
            WHERE t.asset_symbol = v_asset.symbol AND t.status = 'completed';

            -- lending_balance et collateral_balance supprimées
            SELECT COALESCE(SUM(available_balance + staking_balance), 0)
            INTO v_user_balances
            FROM user_balances
            WHERE asset_symbol = v_asset.symbol;

            v_net_position := GREATEST(v_total_credits - v_total_debits, 0);

            INSERT INTO supported_assets_metrics (
                asset_symbol, total_deposited, total_withdrawn,
                total_user_balance, net_position, should_be_in_custody, last_updated
            ) VALUES (
                v_asset.symbol, v_total_credits, v_total_debits,
                v_user_balances, v_net_position, v_user_balances, NOW()
            )
            ON CONFLICT (asset_symbol) DO UPDATE SET
                total_deposited    = EXCLUDED.total_deposited,
                total_withdrawn    = EXCLUDED.total_withdrawn,
                total_user_balance = EXCLUDED.total_user_balance,
                net_position       = EXCLUDED.net_position,
                should_be_in_custody = EXCLUDED.should_be_in_custody,
                last_updated       = NOW();

            RETURN QUERY SELECT v_asset.symbol, 'RECALCULATED',
                format('Credits: %s, Debits: %s, User Balances: %s',
                       v_total_credits, v_total_debits, v_user_balances);

        EXCEPTION WHEN OTHERS THEN
            RETURN QUERY SELECT v_asset.symbol, 'ERROR', format('Erreur: %s', SQLERRM);
        END;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_user_balance(p_user_id uuid, p_asset_symbol text)
 RETURNS TABLE(total_app_balance numeric, net_onchain_balance numeric, other_sources_balance numeric, is_balanced boolean)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_total_app    numeric;
    v_deposited    numeric;
    v_withdrawn    numeric;
    v_net_onchain  numeric;
BEGIN
    SELECT COALESCE(available_balance, 0) + COALESCE(staking_balance, 0)
    INTO v_total_app
    FROM user_balances
    WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol;

    SELECT COALESCE(SUM(amount), 0) INTO v_deposited
    FROM transactions
    WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol
    AND type = 'deposit' AND status = 'completed';

    SELECT COALESCE(SUM(amount), 0) INTO v_withdrawn
    FROM transactions
    WHERE user_id = p_user_id AND asset_symbol = p_asset_symbol
    AND type IN ('withdraw', 'withdrawal') AND status = 'completed';

    v_net_onchain := v_deposited - v_withdrawn;

    RETURN QUERY SELECT
        v_total_app,
        v_net_onchain,
        v_total_app - v_net_onchain,
        (v_total_app >= v_net_onchain);
END;
$function$

CREATE OR REPLACE FUNCTION public.request_user_address(p_user_id uuid, p_asset_symbol text)
 RETURNS TABLE(status text, id uuid, asset_symbol text, network text, address text, derivation_index integer, is_active boolean, cached_balance numeric, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare
  v_service_key text;
  v_request_id bigint;
  v_symbol text := upper(trim(p_asset_symbol));
begin
  if auth.uid() is distinct from p_user_id
     and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Non autorisé';
  end if;

  return query
    select 'ready'::text, ua.id, ua.asset_symbol, ua.network, ua.address,
           ua.derivation_index, ua.is_active, ua.cached_balance, ua.created_at
    from public.user_addresses ua
    where ua.user_id = p_user_id and ua.asset_symbol = v_symbol
    limit 1;
  if found then return; end if;

  if exists (
    select 1 from public.pending_address_requests par
    where par.user_id = p_user_id and par.asset_symbol = v_symbol
      and par.created_at > now() - interval '2 minutes'
  ) then
    return query select 'pending'::text, null::uuid, v_symbol, null::text, null::text,
                        null::integer, null::boolean, null::numeric, null::timestamptz;
    return;
  end if;

  select decrypted_secret into v_service_key
  from vault.decrypted_secrets where name = 'service_role_key';
  if v_service_key is null then
    raise exception 'Configuration serveur invalide (clé service manquante)';
  end if;

  select net.http_post(
    url := 'https://jbzbwyuawejdhhutkmkk.supabase.co/functions/v1/generate-crypto-address',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body := jsonb_build_object('asset_symbol', v_symbol, 'user_id', p_user_id)
  ) into v_request_id;

  insert into public.pending_address_requests (user_id, asset_symbol, request_id)
  values (p_user_id, v_symbol, v_request_id)
  on conflict (user_id, asset_symbol) do update
    set request_id = excluded.request_id, created_at = now();

  return query select 'pending'::text, null::uuid, v_symbol, null::text, null::text,
                      null::integer, null::boolean, null::numeric, null::timestamptz;
end;
$function$

CREATE OR REPLACE FUNCTION public.rollback_airtime_purchase(p_reference_no text, p_amount numeric, p_currency text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_user_id uuid;
BEGIN
  SELECT id, user_id INTO v_tx_id, v_user_id
  FROM transactions
  WHERE metadata->>'referenceNo' = p_reference_no
    AND type = 'airtime_purchase'
    AND status = 'pending'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction non trouvée');
  END IF;

  -- Rembourser l'utilisateur
  PERFORM increment_balance(v_user_id, p_currency, p_amount);

  -- Marquer la transaction comme échouée
  UPDATE transactions 
  SET status = 'failed',
      metadata = metadata || jsonb_build_object('failure_reason', p_reason, 'rolled_back_at', now()),
      completed_at = now()
  WHERE id = v_tx_id;

  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.rollback_mobile_money_withdrawal(p_external_reference text, p_amount numeric, p_asset_symbol text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tx_id uuid;
  v_user_id uuid;
BEGIN
  SELECT id, user_id INTO v_tx_id, v_user_id
  FROM transactions
  WHERE metadata->>'external_reference' = p_external_reference
    AND type = 'withdrawal' AND status = 'pending'
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Transaction de retrait non trouvée');
  END IF;

  -- On passe le statut a 'failed' AVANT de rembourser : si un second appel
  -- concurrent attend sur le verrou, il relira 'failed' et sortira en NOT FOUND.
  UPDATE transactions
  SET status = 'failed',
      metadata = metadata || jsonb_build_object('failure_reason', p_reason, 'rolled_back_at', now()),
      completed_at = now()
  WHERE id = v_tx_id;

  -- Remboursement dans le MEME actif qui avait ete debite (plus jamais FCFA en dur)
  PERFORM increment_balance(v_user_id, p_asset_symbol, p_amount);

  INSERT INTO notifications (user_id, type, title, message, data)
  VALUES (
    v_user_id, 'withdrawal_failed', 'Retrait annulé ❌',
    format('Votre retrait a échoué. %s %s ont été remboursés sur votre compte.', p_amount, p_asset_symbol),
    jsonb_build_object('amount', p_amount, 'reason', p_reason)
  );

  RETURN jsonb_build_object('success', true, 'transaction_id', v_tx_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_new_asset_to_all_users()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Seulement à l'insertion d'un nouvel actif actif
  IF TG_OP = 'INSERT' AND NEW.is_active = true THEN
    -- Créer la ligne pour tous les utilisateurs qui n'ont pas encore cet actif
    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance, staking_balance)
    SELECT u.id, NEW.symbol, 0, 0
    FROM public.users u
    WHERE NOT EXISTS (
      SELECT 1 FROM public.user_balances ub 
      WHERE ub.user_id = u.id AND ub.asset_symbol = NEW.symbol
    );
    
    RAISE NOTICE '✅ Actif % synchronisé pour tous les utilisateurs', NEW.symbol;
  END IF;
  
  -- Si un actif est réactivé (is_active passe de false à true)
  IF TG_OP = 'UPDATE' AND NEW.is_active = true AND (OLD.is_active = false OR OLD.is_active IS NULL) THEN
    INSERT INTO public.user_balances (user_id, asset_symbol, available_balance, staking_balance)
    SELECT u.id, NEW.symbol, 0, 0
    FROM public.users u
    WHERE NOT EXISTS (
      SELECT 1 FROM public.user_balances ub 
      WHERE ub.user_id = u.id AND ub.asset_symbol = NEW.symbol
    );
    
    RAISE NOTICE '✅ Actif réactivé % synchronisé pour tous les utilisateurs', NEW.symbol;
  END IF;
  
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_referral_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Décrémenter l'ancien parrain si referred_by change
  IF TG_OP = 'UPDATE' AND OLD.referred_by IS DISTINCT FROM NEW.referred_by THEN
    IF OLD.referred_by IS NOT NULL THEN
      UPDATE public.users
      SET total_referrals = GREATEST(0, (
        SELECT COUNT(*) FROM public.users WHERE referred_by = OLD.referred_by
      )),
      updated_at = NOW()
      WHERE id = OLD.referred_by;
    END IF;
  END IF;

  -- Incrémenter le nouveau parrain
  IF NEW.referred_by IS NOT NULL THEN
    UPDATE public.users
    SET total_referrals = (
      SELECT COUNT(*) FROM public.users WHERE referred_by = NEW.referred_by
    ),
    updated_at = NOW()
    WHERE id = NEW.referred_by;
  END IF;

  RETURN NEW;
END;
$function$

description:
Capture un snapshot quotidien de l'état de la plateforme.
Idempotent : ne crée pas de doublon si appelé plusieurs fois le même jour.
À planifier via pg_cron : SELECT cron.schedule('0 0 * * *', 'SELECT take_admin_snapshot()');

function_definition:
CREATE OR REPLACE FUNCTION public.trading_purchase_access(p_user_id uuid, p_service_key text, p_target_symbol text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_pricing        public.trading_service_pricing%ROWTYPE;
  v_balance        numeric;
  v_final_price    numeric;
  v_price_usd      numeric;
  v_transaction_id uuid;
  v_grant_id       uuid;
  v_expires_at     timestamp with time zone;
BEGIN

  -- Récupérer la config du service
  SELECT * INTO v_pricing
  FROM public.trading_service_pricing
  WHERE service_key = p_service_key AND is_active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'SERVICE_NOT_FOUND',
      'message', 'Service introuvable ou inactif'
    );
  END IF;

  -- Vérifier si l'user a déjà un accès actif
  IF public.trading_check_access(p_user_id, p_service_key, p_target_symbol) THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'ALREADY_HAS_ACCESS',
      'message', 'Tu as déjà un accès actif pour ce service'
    );
  END IF;

  -- ── Service gratuit ──────────────────────────────────────────
  IF v_pricing.price_amount = 0 THEN

    INSERT INTO public.trading_access_grants (
      user_id, pricing_id, service_key, target_symbol,
      paid_amount, paid_asset, paid_usd_value,
      transaction_id, discount_pct,
      uses_remaining, uses_total, expires_at, status
    ) VALUES (
      p_user_id, v_pricing.id, p_service_key, p_target_symbol,
      0, v_pricing.price_asset, 0,
      NULL, 0,
      v_pricing.uses_included, v_pricing.uses_included,
      NULL, 'active'
    ) RETURNING id INTO v_grant_id;

    INSERT INTO public.notifications (user_id, type, title, message, data)
    VALUES (
      p_user_id, 'trading_access', '✅ Accès gratuit activé',
      format('%s est maintenant disponible', v_pricing.service_name),
      jsonb_build_object(
        'grant_id', v_grant_id, 'service_key', p_service_key, 'is_free', true
      )
    );

    RETURN jsonb_build_object(
      'success', true, 'grant_id', v_grant_id, 'transaction_id', NULL,
      'service_key', p_service_key, 'service_name', v_pricing.service_name,
      'paid_amount', 0, 'paid_asset', v_pricing.price_asset,
      'discount_amount', 0, 'discount_pct', 0,
      'uses_remaining', v_pricing.uses_included, 'expires_at', NULL
    );
  END IF;

  -- ── Service payant ──────────────────────────────────────────
  v_final_price := v_pricing.price_amount;

  -- Vérifier le solde
  SELECT available_balance INTO v_balance
  FROM public.user_balances
  WHERE user_id = p_user_id AND asset_symbol = v_pricing.price_asset
  FOR UPDATE;

  IF NOT FOUND OR v_balance < v_final_price THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'INSUFFICIENT_BALANCE',
      'message', format(
        'Solde insuffisant. Requis: %s %s, Disponible: %s %s',
        v_final_price, v_pricing.price_asset,
        COALESCE(v_balance, 0), v_pricing.price_asset
      ),
      'required', v_final_price,
      'available', COALESCE(v_balance, 0),
      'asset', v_pricing.price_asset
    );
  END IF;

  -- Prix USD
  SELECT price_usd * v_final_price INTO v_price_usd
  FROM public.asset_prices
  WHERE asset_symbol = v_pricing.price_asset;

  -- Expiration
  IF v_pricing.access_duration_minutes IS NOT NULL THEN
    v_expires_at := NOW() + (v_pricing.access_duration_minutes || ' minutes')::interval;
  END IF;

  -- 1. Débiter le solde
  UPDATE public.user_balances
  SET available_balance = available_balance - v_final_price,
      updated_at        = NOW()
  WHERE user_id = p_user_id AND asset_symbol = v_pricing.price_asset;

  -- 2. Transaction
  INSERT INTO public.transactions (
    user_id, type, asset_symbol, amount, fee, net_amount, status, metadata
  ) VALUES (
    p_user_id, 'fee', v_pricing.price_asset,
    v_final_price, 0, v_final_price, 'completed',
    jsonb_build_object(
      'service_key',    p_service_key,
      'service_name',   v_pricing.service_name,
      'target_symbol',  p_target_symbol,
      'original_price', v_pricing.price_amount
    )
  ) RETURNING id INTO v_transaction_id;

  -- 3. Collecter les fees plateforme
  INSERT INTO public.platform_fees (
    asset_symbol, amount, fee_type, source_user_id, source_transaction_id
  ) VALUES (
    v_pricing.price_asset, v_final_price,
    'trading_service', p_user_id, v_transaction_id
  );

  -- 4. Métriques asset
  UPDATE public.supported_assets_metrics
  SET total_fees_collected = total_fees_collected + v_final_price,
      last_updated         = NOW()
  WHERE asset_symbol = v_pricing.price_asset;

  -- 5. Créer le grant d'accès
  INSERT INTO public.trading_access_grants (
    user_id, pricing_id, service_key, target_symbol,
    paid_amount, paid_asset, paid_usd_value,
    transaction_id, discount_pct,
    uses_remaining, uses_total, expires_at, status
  ) VALUES (
    p_user_id, v_pricing.id, p_service_key, p_target_symbol,
    v_final_price, v_pricing.price_asset, v_price_usd,
    v_transaction_id, 0,
    v_pricing.uses_included, v_pricing.uses_included,
    v_expires_at, 'active'
  ) RETURNING id INTO v_grant_id;

  -- 6. Notification
  INSERT INTO public.notifications (user_id, type, title, message, data)
  VALUES (
    p_user_id, 'trading_access', '✅ Accès débloqué',
    format('%s débloqué pour %s %s',
      v_pricing.service_name, v_final_price, v_pricing.price_asset),
    jsonb_build_object(
      'grant_id',    v_grant_id,
      'service_key', p_service_key,
      'symbol',      p_target_symbol
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'grant_id', v_grant_id,
    'transaction_id', v_transaction_id,
    'service_key', p_service_key,
    'service_name', v_pricing.service_name,
    'paid_amount', v_final_price,
    'paid_asset', v_pricing.price_asset,
    'discount_amount', 0,
    'discount_pct', 0,
    'uses_remaining', v_pricing.uses_included,
    'expires_at', v_expires_at
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false, 'error', 'TRANSACTION_FAILED', 'message', SQLERRM
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.transfer_between_users_safe(p_sender_id uuid, p_recipient_id uuid, p_asset_symbol text, p_amount numeric, p_memo text DEFAULT NULL::text)
 RETURNS TABLE(success boolean, message text, transaction_id uuid, fee numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller      uuid;
  v_asset       RECORD;
  v_balance     numeric;
  v_fee         numeric;
  v_net_amount  numeric;
  v_tx_id       uuid;
BEGIN
  -- ── VÉRIFICATION D'IDENTITÉ ─────────────────────────────────────────────────
  -- L'appelant doit être exactement l'expéditeur déclaré.
  -- Exception : service_role / postgres peuvent agir pour le compte d'un user
  -- (ex : remboursement automatique, correction admin).
  v_caller := auth.uid();

  IF current_role NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
    IF v_caller IS NULL THEN
      RETURN QUERY SELECT false, 'Non authentifié', NULL::uuid, 0::numeric;
      RETURN;
    END IF;

    IF v_caller != p_sender_id THEN
      RETURN QUERY SELECT false,
        'Opération non autorisée : vous ne pouvez transférer que depuis votre propre compte',
        NULL::uuid, 0::numeric;
      RETURN;
    END IF;
  END IF;

  -- ── VALIDATIONS DE BASE ──────────────────────────────────────────────────────
  IF p_sender_id = p_recipient_id THEN
    RETURN QUERY SELECT false, 'Impossible de se transférer à soi-même', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  IF p_amount <= 0 THEN
    RETURN QUERY SELECT false, 'Montant invalide', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  -- ── ASSET ────────────────────────────────────────────────────────────────────
  SELECT * INTO v_asset
  FROM public.supported_assets
  WHERE symbol = p_asset_symbol AND is_active = true;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Asset non supporté', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  v_fee        := COALESCE(v_asset.transfer_fee, 0);
  v_net_amount := p_amount - v_fee;

  IF v_net_amount <= 0 THEN
    RETURN QUERY SELECT false,
      format('Montant insuffisant pour couvrir les frais (%s %s)', v_fee, p_asset_symbol),
      NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  -- ── DESTINATAIRE ─────────────────────────────────────────────────────────────
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_recipient_id) THEN
    RETURN QUERY SELECT false, 'Destinataire introuvable', NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  -- ── SOLDE EXPÉDITEUR (verrou anti-race condition) ────────────────────────────
  SELECT available_balance INTO v_balance
  FROM public.user_balances
  WHERE user_id = p_sender_id AND asset_symbol = p_asset_symbol
  FOR UPDATE;

  IF COALESCE(v_balance, 0) < p_amount THEN
    RETURN QUERY SELECT false,
      format('Solde insuffisant. Disponible : %s %s', COALESCE(v_balance, 0), p_asset_symbol),
      NULL::uuid, 0::numeric;
    RETURN;
  END IF;

  -- ── DÉBITER L'EXPÉDITEUR ─────────────────────────────────────────────────────
  UPDATE public.user_balances
  SET available_balance = available_balance - p_amount,
      updated_at        = now()
  WHERE user_id = p_sender_id AND asset_symbol = p_asset_symbol;

  -- ── CRÉDITER LE DESTINATAIRE ─────────────────────────────────────────────────
  INSERT INTO public.user_balances (user_id, asset_symbol, available_balance)
  VALUES (p_recipient_id, p_asset_symbol, v_net_amount)
  ON CONFLICT (user_id, asset_symbol) DO UPDATE
  SET available_balance = user_balances.available_balance + v_net_amount,
      updated_at        = now();

  -- ── TRANSACTION ENVOI ────────────────────────────────────────────────────────
  INSERT INTO public.transactions (
    user_id, type, asset_symbol, amount, fee, status, metadata
  ) VALUES (
    p_sender_id, 'p2p_transfer', p_asset_symbol, p_amount, v_fee, 'completed',
    jsonb_build_object(
      'recipient_id', p_recipient_id,
      'net_amount',   v_net_amount,
      'fee',          v_fee,
      'memo',         p_memo,
      'direction',    'out'
    )
  ) RETURNING id INTO v_tx_id;

  -- ── TRANSACTION RÉCEPTION ────────────────────────────────────────────────────
  INSERT INTO public.transactions (
    user_id, type, asset_symbol, amount, fee, status, reference_id, metadata
  ) VALUES (
    p_recipient_id, 'p2p_transfer', p_asset_symbol, v_net_amount, 0, 'completed',
    v_tx_id,
    jsonb_build_object(
      'sender_id', p_sender_id,
      'memo',      p_memo,
      'direction', 'in'
    )
  );

  -- ── FRAIS PLATEFORME ─────────────────────────────────────────────────────────
  IF v_fee > 0 THEN
    PERFORM public.collect_fee_to_platform(
      p_asset_symbol, v_fee, 'transfer', p_sender_id, v_tx_id
    );
  END IF;

  -- ── NOTIFICATIONS ────────────────────────────────────────────────────────────
  INSERT INTO public.notifications (user_id, type, title, message, data)
  VALUES
  (
    p_sender_id, 'transfer_sent',
    'Transfert envoyé',
    format('%s %s envoyés', v_net_amount, p_asset_symbol),
    jsonb_build_object('recipient_id', p_recipient_id, 'amount', v_net_amount, 'asset', p_asset_symbol)
  ),
  (
    p_recipient_id, 'transfer_received',
    'Transfert reçu',
    format('%s %s reçus', v_net_amount, p_asset_symbol),
    jsonb_build_object('sender_id', p_sender_id, 'amount', v_net_amount, 'asset', p_asset_symbol)
  );

  RETURN QUERY SELECT true,
    format('Transfert réussi : %s %s envoyés (frais : %s)', v_net_amount, p_asset_symbol, v_fee),
    v_tx_id, v_fee;

EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT false, 'Erreur : ' || SQLERRM, NULL::uuid, 0::numeric;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_round_treasury_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.amount := case when round(new.amount, 18) > 0 then round(new.amount, 18) else new.amount end;
  new.balance_before := round(new.balance_before, 18);
  new.balance_after := round(new.balance_after, 18);
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.trg_round_treasury_wallets()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.balance := round(new.balance, 18);
  new.total_collected := round(new.total_collected, 18);
  new.total_withdrawn := round(new.total_withdrawn, 18);
  new.total_burned := round(new.total_burned, 18);
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.trigger_init_asset_metrics()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM initialize_asset_metrics(NEW.symbol);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_staking_config_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_pool_config(p_pool_id uuid)
 RETURNS TABLE(is_valid boolean, errors text[])
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_pool RECORD;
  v_errors TEXT[] := '{}';
  v_config JSONB;
BEGIN
  SELECT * INTO v_pool FROM staking_pools WHERE id = p_pool_id;
  
  IF v_pool IS NULL THEN
    RETURN QUERY SELECT FALSE, ARRAY['Pool not found'];
    RETURN;
  END IF;
  
  -- ✅ Validation des assets
  IF NOT EXISTS(
    SELECT 1 FROM supported_assets 
    WHERE symbol = v_pool.asset_symbol AND is_active = true
  ) THEN
    v_errors := array_append(v_errors, 'Stake asset not found or inactive');
  END IF;
  
  IF v_pool.reward_asset_symbol IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM supported_assets 
    WHERE symbol = v_pool.reward_asset_symbol AND is_active = true
  ) THEN
    v_errors := array_append(v_errors, 'Reward asset not found or inactive');
  END IF;
  
  -- ✅ CORRECTION : Valider les dates depuis launchpool_config pour les pools launchpool
  IF v_pool.apy_mode = 'launchpool' THEN
    v_config := COALESCE(v_pool.launchpool_config, '{}'::jsonb);
    
    IF v_config->>'start_date' IS NULL THEN
      v_errors := array_append(v_errors, 'Launchpool start_date required in config');
    END IF;
    
    IF v_config->>'end_date' IS NULL THEN
      v_errors := array_append(v_errors, 'Launchpool end_date required in config');
    END IF;
    
    -- Vérifier cohérence des dates
    IF v_config->>'start_date' IS NOT NULL AND v_config->>'end_date' IS NOT NULL THEN
      IF (v_config->>'start_date')::timestamp >= (v_config->>'end_date')::timestamp THEN
        v_errors := array_append(v_errors, 'Launchpool start_date must be before end_date');
      END IF;
    END IF;
    
    -- Vérifier total_rewards
    IF v_config->>'total_rewards' IS NULL OR (v_config->>'total_rewards')::numeric <= 0 THEN
      v_errors := array_append(v_errors, 'Launchpool total_rewards must be > 0');
    END IF;
  END IF;
  
  -- ✅ Validation des pourcentages
  IF COALESCE(v_pool.early_claim_penalty_percentage, 0) < 0 
     OR COALESCE(v_pool.early_claim_penalty_percentage, 0) > 100 THEN
    v_errors := array_append(v_errors, 'Early claim penalty must be between 0 and 100');
  END IF;
  
  IF COALESCE(v_pool.instant_unstake_fee_percentage, 0) < 0 
     OR COALESCE(v_pool.instant_unstake_fee_percentage, 0) > 10 THEN
    v_errors := array_append(v_errors, 'Instant unstake fee must be between 0 and 10');
  END IF;
  
  -- ✅ Validation capacités
  IF v_pool.total_capacity IS NOT NULL AND v_pool.total_capacity < v_pool.total_staked THEN
    v_errors := array_append(v_errors, 'Total capacity cannot be less than total staked');
  END IF;
  
  IF v_pool.max_stake IS NOT NULL AND v_pool.min_stake > v_pool.max_stake THEN
    v_errors := array_append(v_errors, 'Min stake cannot be greater than max stake');
  END IF;
  
  RETURN QUERY SELECT 
    (array_length(v_errors, 1) IS NULL OR array_length(v_errors, 1) = 0),
    v_errors;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_user_balance(p_user_id uuid, p_asset_symbol text, p_amount numeric)
 RETURNS TABLE(is_valid boolean, available_balance numeric, required_amount numeric, message text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_balance NUMERIC;
BEGIN
    -- Récupérer le solde disponible
    SELECT available_balance INTO v_balance
    FROM user_balances
    WHERE user_id = p_user_id 
    AND asset_symbol = p_asset_symbol;
    
    -- Si aucun solde trouvé
    IF v_balance IS NULL THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, p_amount, 'Aucun solde trouvé pour cet asset';
        RETURN;
    END IF;
    
    -- Vérifier la suffisance du solde
    IF v_balance >= p_amount THEN
        RETURN QUERY SELECT TRUE, v_balance, p_amount, 'Solde suffisant';
    ELSE
        RETURN QUERY SELECT FALSE, v_balance, p_amount, 
            format('Solde insuffisant. Disponible: %s, Requis: %s', v_balance, p_amount);
    END IF;
END;
$function$
